BOOK.add({
  subject: "math",
  id: "math-09",
  title: "साधारण ब्याज",
  notes: "\n    <h3>1. मूल परिभाषाएँ</h3>\n    <ul>\n      <li><b>मूलधन (Principal, P):</b> वह राशि जो उधार दी या ली जाती है।</li>\n      <li><b>ब्याज (Interest, I):</b> मूलधन के उपयोग के बदले दी जाने वाली अतिरिक्त राशि।</li>\n      <li><b>दर (Rate, R):</b> प्रति ₹100 पर एक वर्ष का ब्याज, यानी \"R% वार्षिक\"।</li>\n      <li><b>समय (Time, T):</b> जितने समय के लिए धन उधार दिया गया — सूत्र में हमेशा <b>वर्षों</b> में लें।</li>\n      <li><b>मिश्रधन (Amount, A):</b> मूलधन + ब्याज, अर्थात A = P + SI।</li>\n      <li><b>साधारण ब्याज (Simple Interest, SI):</b> जब ब्याज हर वर्ष केवल <b>मूल मूलधन</b> पर ही लगे। इसलिए हर वर्ष का ब्याज बराबर रहता है।</li>\n    </ul>\n\n    <h3>2. मुख्य सूत्र</h3>\n    <table>\n      <tr><th>क्या ज्ञात करना है</th><th>सूत्र</th></tr>\n      <tr><td>साधारण ब्याज</td><td>SI = (P × R × T) ÷ 100</td></tr>\n      <tr><td>मूलधन</td><td>P = (SI × 100) ÷ (R × T)</td></tr>\n      <tr><td>दर</td><td>R = (SI × 100) ÷ (P × T)</td></tr>\n      <tr><td>समय</td><td>T = (SI × 100) ÷ (P × R)</td></tr>\n      <tr><td>मिश्रधन</td><td>A = P + SI = P × (100 + R × T) ÷ 100</td></tr>\n      <tr><td>मिश्रधन से मूलधन</td><td>P = (A × 100) ÷ (100 + R × T)</td></tr>\n    </table>\n    <div class=\"tip\">याद रखें: \"PRT बटा 100\" — तीनों का गुणा, 100 से भाग। बाकी तीनों सूत्र इसी को उलटकर बनते हैं।</div>\n\n    <h4>समय का रूपांतरण</h4>\n    <ul>\n      <li>महीने दिए हों तो T = महीने ÷ 12 (जैसे 8 महीने = 8/12 = 2/3 वर्ष)।</li>\n      <li>दिन दिए हों तो T = दिन ÷ 365 (जैसे 73 दिन = 73/365 = 1/5 वर्ष)।</li>\n      <li>3 वर्ष 4 महीने = 3 + 4/12 = 10/3 वर्ष; 2 वर्ष 6 महीने = 2.5 वर्ष।</li>\n      <li>दर यदि \"प्रति माह\" दी हो तो उसे 12 से गुणा करके वार्षिक बनाएँ। जैसे \"₹1 प्रति सैकड़ा प्रति माह\" = 12% वार्षिक।</li>\n      <li>दर यदि \"छमाही\" (अर्धवार्षिक) दी हो तो वार्षिक दर = 2 × छमाही दर।</li>\n    </ul>\n\n    <h4>हल किया गया उदाहरण 1</h4>\n    <p>₹5000 का 8% वार्षिक दर से 3 वर्ष का साधारण ब्याज व मिश्रधन ज्ञात कीजिए।<br>\n    हल: SI = 5000 × 8 × 3 ÷ 100 = ₹1200; मिश्रधन = 5000 + 1200 = ₹6200।</p>\n\n    <h4>हल किया गया उदाहरण 2 (मिश्रधन से मूलधन)</h4>\n    <p>कौन-सी राशि 4% वार्षिक दर से 3 वर्ष में ₹1680 हो जाएगी?<br>\n    हल: 3 वर्ष में ब्याज = 12% → मिश्रधन = मूलधन का 112%।<br>\n    P = 1680 × 100 ÷ 112 = ₹1500।</p>\n\n    <h4>हल किया गया उदाहरण 3 (दो मिश्रधन दिए हों)</h4>\n    <p>कोई राशि 2 वर्ष में ₹7200 तथा 5 वर्ष में ₹9000 हो जाती है। मूलधन व दर?<br>\n    हल: 3 वर्ष का ब्याज = 9000 − 7200 = 1800 → 1 वर्ष का ब्याज = 600।<br>\n    2 वर्ष का ब्याज = 1200 → मूलधन = 7200 − 1200 = ₹6000।<br>\n    दर = 600 × 100 ÷ 6000 = 10%।</p>\n\n    <h3>3. राशि का n गुना होना</h3>\n    <p>यदि राशि n गुना हो जाती है तो ब्याज = (n − 1) × P। इसलिए:</p>\n    <ul>\n      <li><b>R × T = (n − 1) × 100</b></li>\n      <li>दोगुना: R × T = 100; तिगुना: R × T = 200; चार गुना: R × T = 300।</li>\n      <li>उदाहरण: 12.5% दर पर राशि दोगुनी होने में 100 ÷ 12.5 = 8 वर्ष।</li>\n      <li>10% पर तिगुनी होने में 200 ÷ 10 = 20 वर्ष।</li>\n    </ul>\n    <table>\n      <tr><th>दर</th><th>दोगुना होने का समय</th><th>तिगुना होने का समय</th></tr>\n      <tr><td>5%</td><td>20 वर्ष</td><td>40 वर्ष</td></tr>\n      <tr><td>8%</td><td>12.5 वर्ष</td><td>25 वर्ष</td></tr>\n      <tr><td>10%</td><td>10 वर्ष</td><td>20 वर्ष</td></tr>\n      <tr><td>12.5%</td><td>8 वर्ष</td><td>16 वर्ष</td></tr>\n      <tr><td>20%</td><td>5 वर्ष</td><td>10 वर्ष</td></tr>\n      <tr><td>25%</td><td>4 वर्ष</td><td>8 वर्ष</td></tr>\n    </table>\n    <h4>हल किया गया उदाहरण 4</h4>\n    <p>कोई राशि साधारण ब्याज पर 15 वर्ष में चार गुनी हो जाती है। कितने वर्ष में 7 गुनी होगी?<br>\n    हल: 4 गुना → ब्याज = 3P, 15 वर्ष में → 1P ब्याज 5 वर्ष में।<br>\n    7 गुना → ब्याज = 6P → 6 × 5 = 30 वर्ष।</p>\n\n    <h3>4. जब SI मूलधन का भिन्न हो और R = T</h3>\n    <p>यदि SI = मूलधन का k भाग और दर = समय (संख्यात्मक रूप से), तो R² = 100k, अर्थात R = √(100k)।<br>\n    उदाहरण: SI = मूलधन का 9/16, R = T → R² = 900/16 → R = 30/4 = 7.5%।</p>\n\n    <h3>5. दर बदलने पर ब्याज में अंतर</h3>\n    <ul>\n      <li>दर में r% का अंतर, समय T: ब्याज का अंतर = P × r × T ÷ 100।</li>\n      <li>उदाहरण: दर 2% बढ़ाने पर 3 वर्ष में ₹360 अधिक मिलते → P = 360 × 100 ÷ (2 × 3) = ₹6000।</li>\n      <li>अलग-अलग अवधियों में अलग दरें हों तो कुल प्रतिशत जोड़ लें: 2 वर्ष 5% + 3 वर्ष 8% + 2 वर्ष 10% = 10 + 24 + 20 = 54% → SI = P का 54%।</li>\n    </ul>\n\n    <h3>6. धन को दो भागों में बाँटना</h3>\n    <h4>(क) कुल ब्याज दिया हो (मिश्रण विधि / Alligation)</h4>\n    <p>₹10000 का कुछ भाग 8% पर व शेष 10% पर दिया। वार्षिक ब्याज ₹860 मिला। 8% पर कितना?<br>\n    हल: औसत दर = 860 ÷ 10000 × 100 = 8.6%।<br>\n    मिश्रण नियम: (10 − 8.6) : (8.6 − 8) = 1.4 : 0.6 = 7 : 3 → 8% पर = 10000 × 7/10 = ₹7000।</p>\n    <h4>(ख) दोनों भागों का ब्याज बराबर हो</h4>\n    <p>यदि भाग x व y पर ब्याज बराबर है: x × R₁ × T₁ = y × R₂ × T₂ → x : y = 1/(R₁T₁) : 1/(R₂T₂)।<br>\n    उदाहरण: ₹3900 के दो भाग, पहले पर 4% से 3 वर्ष का ब्याज = दूसरे पर 6% से 4 वर्ष का ब्याज → 12x = 24y → x : y = 2 : 1 → पहला भाग = ₹2600।</p>\n    <h4>(ग) दोनों भागों का मिश्रधन बराबर हो</h4>\n    <p>x(100 + R T₁) = y(100 + R T₂)।<br>\n    उदाहरण: ₹4600 के दो भाग, 5% दर पर पहले का 2 वर्ष बाद का मिश्रधन = दूसरे का 4 वर्ष बाद का मिश्रधन → 110x = 120y → x : y = 12 : 11 → पहला = 4600 × 12/23 = ₹2400।</p>\n\n    <h3>7. समान वार्षिक किश्तें (साधारण ब्याज पर)</h3>\n    <p>यदि कोई ऋण (मिश्रधन) A, n वर्ष बाद देय है और उसे n समान वार्षिक किश्तों (प्रत्येक x) में, R% साधारण ब्याज पर चुकाना है तो —</p>\n    <ul>\n      <li>पहली किश्त (n − 1) वर्ष तक, दूसरी (n − 2) वर्ष तक ... ब्याज कमाती है, अंतिम किश्त पर कोई ब्याज नहीं।</li>\n      <li>A = n·x + x × R × [1 + 2 + ... + (n − 1)] ÷ 100</li>\n      <li><b>x = (100 × A) ÷ [100 × n + R × n(n − 1) ÷ 2]</b></li>\n    </ul>\n    <h4>हल किया गया उदाहरण 5</h4>\n    <p>₹1092 का ऋण, जो 3 वर्ष बाद देय है, 12% साधारण ब्याज पर किस समान वार्षिक किश्त से चुकेगा?<br>\n    हल: x = 1092 × 100 ÷ (300 + 12 × 3) = 109200 ÷ 336 = ₹325।<br>\n    जाँच: 325 पर 2 वर्ष ब्याज 78, 1 वर्ष ब्याज 39 → 325 × 3 + 78 + 39 = 1092 ✓</p>\n\n    <h3>8. औसत दर</h3>\n    <p>₹2000 को 5% पर और ₹3000 को 6% पर 2 वर्ष के लिए दिया → कुल ब्याज = 200 + 360 = 560; औसत दर = 560 × 100 ÷ (5000 × 2) = 5.6%।</p>\n    <p>1/3 भाग 3% पर, 1/6 भाग 6% पर और शेष (1/2) 8% पर → औसत दर = 1 + 1 + 4 = 6%।</p>\n\n    <h3>9. चक्रवृद्धि ब्याज — परिचय</h3>\n    <p>चक्रवृद्धि ब्याज (Compound Interest, CI) में हर अवधि के अंत में ब्याज मूलधन में जुड़ जाता है और अगली अवधि का ब्याज नए (बढ़े हुए) मूलधन पर लगता है।</p>\n    <table>\n      <tr><th>स्थिति</th><th>मिश्रधन का सूत्र</th></tr>\n      <tr><td>वार्षिक संयोजन</td><td>A = P × (1 + R/100)<sup>n</sup></td></tr>\n      <tr><td>अर्धवार्षिक (छमाही) संयोजन</td><td>A = P × (1 + R/200)<sup>2n</sup> (दर आधी, अवधियाँ दोगुनी)</td></tr>\n      <tr><td>त्रैमासिक संयोजन</td><td>A = P × (1 + R/400)<sup>4n</sup></td></tr>\n      <tr><td>चक्रवृद्धि ब्याज</td><td>CI = A − P</td></tr>\n    </table>\n    <h4>हल किया गया उदाहरण 6</h4>\n    <p>₹8000 पर 10% वार्षिक दर से 1.5 वर्ष का चक्रवृद्धि ब्याज, जब ब्याज अर्धवार्षिक जुड़ता हो।<br>\n    हल: छमाही दर = 5%, अवधियाँ = 3 → A = 8000 × (1.05)³ = 8000 × 1.157625 = ₹9261 → CI = ₹1261।</p>\n\n    <h3>10. CI और SI का अंतर</h3>\n    <table>\n      <tr><th>समय</th><th>CI − SI</th></tr>\n      <tr><td>1 वर्ष</td><td>0 (वार्षिक संयोजन में दोनों बराबर)</td></tr>\n      <tr><td>2 वर्ष</td><td>P × (R/100)²</td></tr>\n      <tr><td>3 वर्ष</td><td>P × (R/100)² × (3 + R/100)</td></tr>\n    </table>\n    <ul>\n      <li>2 वर्ष: ₹10000, 5% → अंतर = 10000 × 1/400 = ₹25।</li>\n      <li>3 वर्ष: ₹10000, 10% → अंतर = 10000 × 1/100 × 3.1 = ₹310 (CI = 3310, SI = 3000)।</li>\n      <li>2 वर्ष में SI व CI दिए हों: R = 2 × (CI − SI) × 100 ÷ SI।</li>\n    </ul>\n\n    <h3>11. साधारण बनाम चक्रवृद्धि — तुलना</h3>\n    <table>\n      <tr><th>बिंदु</th><th>साधारण ब्याज</th><th>चक्रवृद्धि ब्याज</th></tr>\n      <tr><td>ब्याज किस पर</td><td>केवल मूल मूलधन पर</td><td>पिछले मिश्रधन पर</td></tr>\n      <tr><td>हर वर्ष का ब्याज</td><td>बराबर</td><td>बढ़ता जाता है</td></tr>\n      <tr><td>मिश्रधन का क्रम</td><td>समांतर श्रेणी (AP)</td><td>गुणोत्तर श्रेणी (GP)</td></tr>\n      <tr><td>पहले वर्ष का ब्याज</td><td colspan=\"2\">दोनों में बराबर (वार्षिक संयोजन)</td></tr>\n    </table>\n    <div class=\"tip\">परीक्षा में \"ब्याज\" लिखा हो और \"चक्रवृद्धि\" न लिखा हो, तो साधारण ब्याज ही मानें।</div>\n  ",
  extra: "\n    <h3>शॉर्टकट व गहन ट्रिक्स</h3>\n    <ul>\n      <li><b>प्रतिशत-विधि:</b> R × T को \"मूलधन का कुल प्रतिशत\" मानें। 6% पर 4 वर्ष = 24% → मिश्रधन = 124%। यदि मिश्रधन ₹6200 है तो 124% = 6200 → 100% = ₹5000। सूत्र लिखने की ज़रूरत नहीं।</li>\n      <li><b>दो मिश्रधन ट्रिक:</b> T₁ वर्ष में A₁ और T₂ वर्ष में A₂ → एक वर्ष का ब्याज = (A₂ − A₁) ÷ (T₂ − T₁); मूलधन = (A₁T₂ − A₂T₁) ÷ (T₂ − T₁)। उदाहरण: 5 वर्ष में 9800, 8 वर्ष में 12005 → P = (9800 × 8 − 12005 × 5) ÷ 3 = (78400 − 60025) ÷ 3 = ₹6125।</li>\n      <li><b>n गुना ट्रिक:</b> यदि राशि T वर्ष में m गुनी होती है तो n गुनी होने का समय = T × (n − 1) ÷ (m − 1)। उदाहरण: 15 वर्ष में 4 गुनी → 7 गुनी = 15 × 6 ÷ 3 = 30 वर्ष।</li>\n      <li><b>सभी चीज़ें गुणा:</b> P, R, T को क्रमशः a, b, c गुना करें तो SI = a × b × c गुना हो जाता है। तीनों दोगुने → 8 गुना।</li>\n      <li><b>दर का अंतर:</b> दो दरों पर एक ही राशि का ब्याज-अंतर दिया हो तो सीधा P = अंतर × 100 ÷ (दर-अंतर × समय)। मध्यस्थ (B, A से 8% पर लेकर C को 11% पर दे) का लाभ = P × 3 × T ÷ 100।</li>\n      <li><b>किश्त ट्रिक:</b> किश्त-प्रश्न में हर किश्त को 100 इकाई मानें। 3 किश्तें, 12% → 100 + 112 + 124 = 336 इकाई = ऋण। 336 इकाई = 1092 → 100 इकाई = 325। यही विधि 4 या 5 किश्तों में भी चलती है (5% पर 4 किश्तें: 100 + 105 + 110 + 115 = 430 इकाई)।</li>\n      <li><b>मिश्रण (Alligation):</b> दो दरों पर बँटी राशि में \"औसत दर\" निकालकर कैंची-गुणा करें — अनुपात सीधे मिलता है।</li>\n      <li><b>R = T वाली स्थिति:</b> SI/P = R²/100। SI = P का 1/4 → R = 5; 9/16 → 7.5; 4/9 → 20/3 = 6 2/3%।</li>\n      <li><b>CI−SI (2 वर्ष):</b> अंतर = SI के ब्याज जैसा है: पहले वर्ष के ब्याज (P × R/100) पर R% ब्याज। इसलिए अंतर = (पहले वर्ष का ब्याज) × R/100।</li>\n      <li><b>CI−SI (3 वर्ष) ट्रिक:</b> अंतर = P(R/100)²(3 + R/100)। R = 10% पर गुणक 0.031, R = 5% पर 0.007625, R = 20% पर 0.128।</li>\n      <li><b>CI में गुणा श्रृंखला:</b> CI से राशि T वर्ष में k गुनी हो तो 2T में k², 3T में k³ गुनी। (5 वर्ष में दोगुनी → 15 वर्ष में 8 गुनी)। साधारण ब्याज में ऐसा नहीं — वहाँ वृद्धि रैखिक है।</li>\n      <li><b>लगातार दो वर्षों के CI-मिश्रधन:</b> अगले वर्ष का मिश्रधन ÷ पिछले वर्ष का मिश्रधन = 1 + R/100। 1210 और 1331 → 1331/1210 = 1.1 → R = 10%।</li>\n      <li><b>सावधानी:</b> \"प्रति माह\" दर, \"छमाही\" दर, दिनों में समय — सबसे पहले इकाई ठीक करें; अधिकांश गलतियाँ यहीं होती हैं।</li>\n    </ul>\n  ",
  questions: [
    {"q":"₹5000 का 8% वार्षिक दर से 3 वर्ष का साधारण ब्याज कितना होगा?","o":["₹1000","₹1200","₹1250","₹1500"],"a":1,"e":"<b>हल:</b><br>चरण 1: सूत्र — साधारण ब्याज SI = (P × R × T) ÷ 100<br>चरण 2: दिया है P = ₹5000, R = 8%, T = 3 वर्ष<br>चरण 3: SI = 5000 × 8 × 3 ÷ 100 = 50 × 24 = 1200<br>अतः उत्तर = <b>₹1200</b><br><b>शॉर्टकट:</b> 3 वर्ष में कुल 8 × 3 = 24% ब्याज → 5000 का 24% = ₹1200<br><b>ध्यान दें:</b> ₹1500 तब आता है जब दर 10% मान लें; ब्याज पूछा है, मिश्रधन नहीं।"},
    {"q":"₹2400 का 5% वार्षिक साधारण ब्याज की दर से 4 वर्ष का मिश्रधन क्या होगा?","o":["₹2880","₹2780","₹2900","₹2480"],"a":0,"e":"<b>हल:</b><br>चरण 1: सूत्र — SI = P × R × T ÷ 100, मिश्रधन A = P + SI<br>चरण 2: SI = 2400 × 5 × 4 ÷ 100 = 24 × 20 = ₹480<br>चरण 3: A = 2400 + 480 = ₹2880<br>अतः उत्तर = <b>₹2880</b><br><b>शॉर्टकट:</b> 4 वर्ष में 20% ब्याज → A = 2400 × 120/100 = ₹2880<br><b>ध्यान दें:</b> ₹2480 मिश्रधन में केवल 1 वर्ष का ब्याज (₹120) जोड़ने की भूल से आता है।"},
    {"q":"₹3000 पर 3 वर्ष का साधारण ब्याज ₹900 है। वार्षिक ब्याज दर क्या है?","o":["8%","9%","10%","12%"],"a":2,"e":"<b>हल:</b><br>चरण 1: सूत्र — R = (SI × 100) ÷ (P × T)<br>चरण 2: दिया है SI = ₹900, P = ₹3000, T = 3 वर्ष<br>चरण 3: R = 900 × 100 ÷ (3000 × 3) = 90000 ÷ 9000 = 10<br>अतः उत्तर = <b>10%</b><br><b>शॉर्टकट:</b> 1 वर्ष का ब्याज = 900 ÷ 3 = 300; 300, 3000 का 10% है।"},
    {"q":"किस मूलधन पर 12% वार्षिक दर से 4 वर्ष का साधारण ब्याज ₹1440 होगा?","o":["₹2800","₹3200","₹3600","₹3000"],"a":3,"e":"<b>हल:</b><br>चरण 1: सूत्र — P = (SI × 100) ÷ (R × T)<br>चरण 2: दिया है SI = ₹1440, R = 12%, T = 4 वर्ष<br>चरण 3: P = 1440 × 100 ÷ (12 × 4) = 144000 ÷ 48 = 3000<br>अतः उत्तर = <b>₹3000</b><br><b>शॉर्टकट:</b> 4 वर्ष में कुल 48% ब्याज = ₹1440 → 1% = 30 → 100% = ₹3000"},
    {"q":"₹6000 पर 10% वार्षिक दर से कितने समय में साधारण ब्याज ₹1800 होगा?","o":["2 वर्ष","2.5 वर्ष","3 वर्ष","4 वर्ष"],"a":2,"e":"<b>हल:</b><br>चरण 1: सूत्र — T = (SI × 100) ÷ (P × R)<br>चरण 2: दिया है SI = ₹1800, P = ₹6000, R = 10%<br>चरण 3: T = 1800 × 100 ÷ (6000 × 10) = 180000 ÷ 60000 = 3<br>अतः उत्तर = <b>3 वर्ष</b><br><b>शॉर्टकट:</b> 1 वर्ष का ब्याज = 6000 का 10% = 600 → 1800 ÷ 600 = 3 वर्ष"},
    {"q":"साधारण ब्याज पर कोई राशि 8 वर्ष में दोगुनी हो जाती है। वार्षिक दर क्या है?","o":["10%","12%","15%","12.5%"],"a":3,"e":"<b>हल:</b><br>चरण 1: राशि दोगुनी = P से 2P, अतः ब्याज SI = 2P − P = P<br>चरण 2: SI = P × R × T ÷ 100 → P = P × R × 8 ÷ 100<br>चरण 3: R × 8 = 100 → R = 100 ÷ 8 = 12.5<br>अतः उत्तर = <b>12.5%</b><br><b>शॉर्टकट:</b> n गुना होने पर R × T = (n − 1) × 100 → R = 100 ÷ 8 = 12.5%<br><b>ध्यान दें:</b> दोगुना होने का अर्थ ब्याज = मूलधन (100%) है, 200% नहीं।"},
    {"q":"10% वार्षिक साधारण ब्याज पर कोई राशि कितने वर्ष में तिगुनी हो जाएगी?","o":["20 वर्ष","10 वर्ष","15 वर्ष","30 वर्ष"],"a":0,"e":"<b>हल:</b><br>चरण 1: राशि तिगुनी = P से 3P, अतः ब्याज = 3P − P = 2P यानी मूलधन का 200%<br>चरण 2: R × T = 200 (सूत्र: n गुना → R × T = (n − 1) × 100)<br>चरण 3: T = 200 ÷ 10 = 20<br>अतः उत्तर = <b>20 वर्ष</b><br><b>ध्यान दें:</b> 30 वर्ष तब आता है जब ब्याज को 3P मान लें; तिगुने में मूलधन भी शामिल है, इसलिए ब्याज केवल 2P है।"},
    {"q":"साधारण ब्याज पर कोई राशि 15 वर्ष में चार गुनी हो जाती है। वह कितने वर्ष में 7 गुनी होगी?","o":["25 वर्ष","30 वर्ष","35 वर्ष","45 वर्ष"],"a":1,"e":"<b>हल:</b><br>चरण 1: 4 गुना → ब्याज = 4P − P = 3P, जो 15 वर्ष में मिलता है<br>चरण 2: 1P ब्याज मिलने में समय = 15 ÷ 3 = 5 वर्ष<br>चरण 3: 7 गुना → ब्याज = 7P − P = 6P → समय = 6 × 5 = 30 वर्ष<br>अतः उत्तर = <b>30 वर्ष</b><br><b>शॉर्टकट:</b> T₂ = T₁ × (n₂ − 1)/(n₁ − 1) = 15 × 6/3 = 30 वर्ष<br><b>ध्यान दें:</b> 15 × 7/4 ≈ 26 या 35 जैसे उत्तर गुणज (n) का सीधा अनुपात लेने से आते हैं; अनुपात (n − 1) का लें।"},
    {"q":"कोई राशि साधारण ब्याज पर 2 वर्ष में ₹7200 तथा 5 वर्ष में ₹9000 हो जाती है। ब्याज दर क्या है?","o":["8%","10%","12%","12.5%"],"a":1,"e":"<b>हल:</b><br>चरण 1: 5 वर्ष का मिश्रधन − 2 वर्ष का मिश्रधन = 3 वर्ष का ब्याज = 9000 − 7200 = ₹1800<br>चरण 2: 1 वर्ष का ब्याज = 1800 ÷ 3 = ₹600<br>चरण 3: मूलधन = 7200 − 2 वर्ष का ब्याज = 7200 − 1200 = ₹6000<br>चरण 4: R = 600 × 100 ÷ 6000 = 10<br>अतः उत्तर = <b>10%</b><br><b>ध्यान दें:</b> दर निकालने के लिए 1 वर्ष के ब्याज को मूलधन (6000) से भाग दें, 7200 से नहीं (600/7200 ≈ 8.3% गलत)।"},
    {"q":"₹4500 का 8% वार्षिक दर से 8 महीने का साधारण ब्याज कितना होगा?","o":["₹240","₹260","₹288","₹300"],"a":0,"e":"<b>हल:</b><br>चरण 1: समय को वर्षों में बदलें — 8 महीने = 8/12 = 2/3 वर्ष<br>चरण 2: SI = P × R × T ÷ 100 = 4500 × 8 × (2/3) ÷ 100<br>चरण 3: = 4500 × 16 ÷ 300 = 72000 ÷ 300 = 240<br>अतः उत्तर = <b>₹240</b><br><b>शॉर्टकट:</b> 1 वर्ष का ब्याज = 360 → 1 माह = 30 → 8 माह = ₹240<br><b>ध्यान दें:</b> ₹288 तब आता है जब 8 महीने को 0.8 वर्ष मान लें — महीनों को हमेशा 12 से भाग दें।"},
    {"q":"₹12000 का 7.5% वार्षिक दर से 2.5 वर्ष का साधारण ब्याज ज्ञात कीजिए।","o":["₹2000","₹2150","₹2250","₹2400"],"a":2,"e":"<b>हल:</b><br>चरण 1: सूत्र — SI = P × R × T ÷ 100<br>चरण 2: SI = 12000 × 7.5 × 2.5 ÷ 100 = 120 × 18.75<br>चरण 3: 120 × 18.75 = 2250<br>अतः उत्तर = <b>₹2250</b><br><b>शॉर्टकट:</b> कुल प्रतिशत = 7.5 × 2.5 = 18.75% → 12000 का 18.75% = 12000 × 3/16 = ₹2250"},
    {"q":"किसी राशि पर साधारण ब्याज मूलधन का 1/4 है। यदि दर (%) और समय (वर्ष) संख्यात्मक रूप से बराबर हों तो दर क्या है?","o":["4%","6%","5%","2.5%"],"a":2,"e":"<b>हल:</b><br>चरण 1: SI/P = R × T ÷ 100 और R = T (संख्यात्मक रूप से)<br>चरण 2: अतः R² ÷ 100 = 1/4 → R² = 100/4 = 25<br>चरण 3: R = √25 = 5<br>अतः उत्तर = <b>5%</b> (और समय 5 वर्ष)<br><b>ध्यान दें:</b> 2.5% तब आता है जब R² के स्थान पर 2R मान लें।"},
    {"q":"किसी राशि पर साधारण ब्याज मूलधन का 9/16 है तथा दर (%) व समय (वर्ष) संख्यात्मक रूप से बराबर हैं। दर ज्ञात कीजिए।","o":["7%","6.5%","8%","7.5%"],"a":3,"e":"<b>हल:</b><br>चरण 1: SI/P = R × T ÷ 100 तथा R = T → R²/100 = 9/16<br>चरण 2: R² = 900/16 = 56.25<br>चरण 3: R = √56.25 = 30/4 = 7.5<br>अतः उत्तर = <b>7.5%</b><br><b>शॉर्टकट:</b> R = 10 × √(9/16) = 10 × 3/4 = 7.5%"},
    {"q":"₹10000 का कुछ भाग 8% तथा शेष 10% वार्षिक साधारण ब्याज पर दिया गया। एक वर्ष का कुल ब्याज ₹860 है। 8% पर दी गई राशि कितनी है?","o":["₹6000","₹7000","₹3000","₹6500"],"a":1,"e":"<b>हल:</b><br>चरण 1: माना 8% पर ₹x और 10% पर ₹(10000 − x)<br>चरण 2: कुल ब्याज: 0.08x + 0.10(10000 − x) = 860 → 1000 − 0.02x = 860<br>चरण 3: 0.02x = 140 → x = 7000<br>अतः उत्तर = <b>₹7000</b><br><b>शॉर्टकट (मिश्रण नियम):</b> औसत दर = 860/10000 = 8.6% → (10 − 8.6) : (8.6 − 8) = 1.4 : 0.6 = 7 : 3 → 8% वाला भाग = 10000 × 7/10 = ₹7000<br><b>ध्यान दें:</b> ₹3000 दूसरे (10%) भाग की राशि है।"},
    {"q":"₹1092 का ऋण, जो 3 वर्ष बाद देय है, 12% वार्षिक साधारण ब्याज पर किस समान वार्षिक किश्त से चुकाया जा सकता है?","o":["₹364","₹300","₹325","₹350"],"a":2,"e":"<b>हल:</b><br>चरण 1: माना प्रत्येक वार्षिक किश्त ₹x है, जो प्रत्येक वर्ष के अंत में दी जाती है<br>चरण 2: पहली किश्त पर 2 वर्ष, दूसरी पर 1 वर्ष, तीसरी पर 0 वर्ष का ब्याज बनता है → कुल ब्याज = x × 12 × (2 + 1 + 0) ÷ 100 = 0.36x<br>चरण 3: किश्तों का कुल मूल्य = 3x + 0.36x = 3.36x = 1092<br>चरण 4: x = 1092 ÷ 3.36 = 325<br>अतः उत्तर = <b>₹325</b><br><b>शॉर्टकट:</b> x = 100A ÷ [100T + R × T(T − 1)/2] = 109200 ÷ (300 + 36) = ₹325<br><b>ध्यान दें:</b> ₹364 = 1092 ÷ 3 है, जो ब्याज को अनदेखा करने से आता है।"},
    {"q":"₹848 का ऋण, जो 4 वर्ष बाद देय है, 4% वार्षिक साधारण ब्याज पर किस समान वार्षिक किश्त से चुकेगा?","o":["₹200","₹212","₹180","₹220"],"a":0,"e":"<b>हल:</b><br>चरण 1: माना प्रत्येक वार्षिक किश्त ₹x; किश्तों पर ब्याज क्रमशः 3, 2, 1, 0 वर्ष का बनता है<br>चरण 2: कुल ब्याज = x × 4 × (3 + 2 + 1 + 0) ÷ 100 = 0.24x<br>चरण 3: 4x + 0.24x = 4.24x = 848 → x = 848 ÷ 4.24 = 200<br>अतः उत्तर = <b>₹200</b><br><b>शॉर्टकट:</b> x = 100A ÷ [100T + R × T(T − 1)/2] = 84800 ÷ (400 + 24) = ₹200<br><b>ध्यान दें:</b> ₹212 = 848 ÷ 4 है, जो ब्याज को अनदेखा करने से आता है।"},
    {"q":"यदि ब्याज दर 2% अधिक होती तो किसी राशि पर 3 वर्ष में ₹360 अधिक ब्याज मिलता। राशि कितनी है?","o":["₹5000","₹4500","₹7200","₹6000"],"a":3,"e":"<b>हल:</b><br>चरण 1: दर 2% बढ़ने पर अतिरिक्त ब्याज = P × 2 × 3 ÷ 100 (केवल बढ़ी हुई दर पर)<br>चरण 2: P × 6 ÷ 100 = 360<br>चरण 3: P = 360 × 100 ÷ 6 = 6000<br>अतः उत्तर = <b>₹6000</b><br><b>शॉर्टकट:</b> 3 वर्ष में 6% अधिक = ₹360 → 1% = 60 → 100% = ₹6000<br><b>ध्यान दें:</b> ₹7200 तब आता है जब 3 वर्ष से गुणा करना भूल जाएँ (360 × 100 ÷ 5 नहीं, ÷ 6)।"},
    {"q":"कोई राशि पहले 2 वर्ष 5%, अगले 3 वर्ष 8% तथा उसके बाद 10% वार्षिक साधारण ब्याज पर है। 7 वर्ष का कुल ब्याज ₹5400 हो तो मूलधन क्या है?","o":["₹9000","₹10000","₹12000","₹10800"],"a":1,"e":"<b>हल:</b><br>चरण 1: कुल 7 वर्ष = पहले 2 वर्ष (5%) + अगले 3 वर्ष (8%) + शेष 2 वर्ष (10%)<br>चरण 2: कुल प्रतिशत ब्याज = 2 × 5 + 3 × 8 + 2 × 10 = 10 + 24 + 20 = 54%<br>चरण 3: P का 54% = 5400 → P = 5400 × 100 ÷ 54 = 10000<br>अतः उत्तर = <b>₹10000</b><br><b>ध्यान दें:</b> अंतिम अवधि 7 − 2 − 3 = 2 वर्ष है; इसे भूलने से गलत प्रतिशत आता है।"},
    {"q":"A ने B को ₹5000, 8% वार्षिक साधारण ब्याज पर दिए। B ने वही राशि C को 11% वार्षिक पर दे दी। 3 वर्ष में B का लाभ कितना है?","o":["₹400","₹450","₹500","₹550"],"a":1,"e":"<b>हल:</b><br>चरण 1: B, A को 8% देता है और C से 11% लेता है → B का शुद्ध लाभ दर = 11 − 8 = 3% वार्षिक<br>चरण 2: B का लाभ = 5000 × 3 × 3 ÷ 100<br>चरण 3: = 45000 ÷ 100 = 450<br>अतः उत्तर = <b>₹450</b><br><b>ध्यान दें:</b> ₹550 = 5000 × 11 × 1 ÷ 100 है; लाभ केवल दरों के अंतर पर बनता है।"},
    {"q":"₹4600 को दो भागों में ऐसे बाँटा गया कि 5% वार्षिक साधारण ब्याज पर पहले भाग का 2 वर्ष बाद का मिश्रधन, दूसरे भाग के 4 वर्ष बाद के मिश्रधन के बराबर हो। पहला भाग कितना है?","o":["₹2200","₹2300","₹2500","₹2400"],"a":3,"e":"<b>हल:</b><br>चरण 1: माना पहला भाग x, दूसरा y। 5% पर 2 वर्ष में कुल 10% ब्याज → मिश्रधन = x × 110/100; 4 वर्ष में 20% → मिश्रधन = y × 120/100<br>चरण 2: 110x = 120y → x : y = 120 : 110 = 12 : 11<br>चरण 3: x = 4600 × 12/23 = 200 × 12 = 2400<br>अतः उत्तर = <b>₹2400</b> (जाँच: 2400 × 1.1 = 2640 = 2200 × 1.2)<br><b>शॉर्टकट:</b> भाग, (100 + R × T) के व्युत्क्रम अनुपात में होते हैं → 1/110 : 1/120 = 12 : 11<br><b>ध्यान दें:</b> ₹2200 दूसरा भाग है।"},
    {"q":"₹3900 को दो भागों में ऐसे बाँटा कि पहले भाग पर 4% से 3 वर्ष का साधारण ब्याज, दूसरे भाग पर 6% से 4 वर्ष के साधारण ब्याज के बराबर हो। पहला भाग?","o":["₹2600","₹1300","₹2340","₹1950"],"a":0,"e":"<b>हल:</b><br>चरण 1: पहले भाग x पर ब्याज = x × 4 × 3 ÷ 100 = 12x/100; दूसरे भाग y पर = y × 6 × 4 ÷ 100 = 24y/100<br>चरण 2: 12x = 24y → x : y = 24 : 12 = 2 : 1<br>चरण 3: पहला भाग = 3900 × 2/3 = 2600<br>अतः उत्तर = <b>₹2600</b><br><b>शॉर्टकट:</b> ब्याज बराबर हों तो भाग (R × T) के व्युत्क्रम अनुपात में → 1/12 : 1/24 = 2 : 1<br><b>ध्यान दें:</b> ₹1300 दूसरा भाग है।"},
    {"q":"₹10000 का 10% वार्षिक दर से 2 वर्ष का चक्रवृद्धि ब्याज (वार्षिक संयोजन) कितना होगा?","o":["₹2000","₹2050","₹2100","₹2200"],"a":2,"e":"<b>हल:</b><br>चरण 1: सूत्र — A = P(1 + R/100)ᵀ, CI = A − P<br>चरण 2: A = 10000 × (1.1)² = 10000 × 1.21 = 12100<br>चरण 3: CI = 12100 − 10000 = 2100<br>अतः उत्तर = <b>₹2100</b><br><b>शॉर्टकट:</b> 2 वर्ष का प्रभावी दर = R + R + R²/100 = 10 + 10 + 1 = 21% → 10000 का 21% = ₹2100<br><b>ध्यान दें:</b> ₹2000 साधारण ब्याज है।"},
    {"q":"₹8000 का 5% वार्षिक चक्रवृद्धि दर से 2 वर्ष का मिश्रधन क्या होगा?","o":["₹8800","₹8820","₹8840","₹8400"],"a":1,"e":"<b>हल:</b><br>चरण 1: सूत्र — A = P(1 + R/100)ᵀ<br>चरण 2: A = 8000 × (1.05)² = 8000 × 1.1025<br>चरण 3: = 8820<br>अतः उत्तर = <b>₹8820</b><br><b>शॉर्टकट:</b> 5% के लिए 2 वर्ष का प्रभावी दर = 5 + 5 + 0.25 = 10.25% → 8000 का 10.25% = 820 → A = ₹8820<br><b>ध्यान दें:</b> ₹8800 साधारण ब्याज वाला मिश्रधन है।"},
    {"q":"₹4000 पर 10% वार्षिक दर से 1 वर्ष का चक्रवृद्धि ब्याज, जब ब्याज अर्धवार्षिक जुड़ता हो, कितना होगा?","o":["₹400","₹420","₹405","₹410"],"a":3,"e":"<b>हल:</b><br>चरण 1: अर्धवार्षिक संयोजन → दर = 10/2 = 5% प्रति छमाही, अवधियाँ = 1 × 2 = 2<br>चरण 2: A = 4000 × (1.05)² = 4000 × 1.1025 = 4410<br>चरण 3: CI = 4410 − 4000 = 410<br>अतः उत्तर = <b>₹410</b><br><b>शॉर्टकट:</b> प्रभावी दर = 5 + 5 + 0.25 = 10.25% → 4000 का 10.25% = ₹410<br><b>ध्यान दें:</b> ₹400 वार्षिक संयोजन (या साधारण ब्याज) से आता है।"},
    {"q":"₹5000 पर 4% वार्षिक दर से 2 वर्ष के चक्रवृद्धि ब्याज और साधारण ब्याज का अंतर कितना है?","o":["₹8","₹10","₹16","₹4"],"a":0,"e":"<b>हल:</b><br>चरण 1: 2 वर्ष के लिए सूत्र — CI − SI = P × (R/100)²<br>चरण 2: = 5000 × (4/100)² = 5000 × 16/10000<br>चरण 3: = 80000/10000 = 8<br>अतः उत्तर = <b>₹8</b><br><b>ध्यान दें:</b> अंतर पहले वर्ष के ब्याज (₹200) पर दूसरे वर्ष का ब्याज है: 200 का 4% = ₹8।"},
    {"q":"किसी राशि पर 5% वार्षिक दर से 2 वर्ष के चक्रवृद्धि और साधारण ब्याज का अंतर ₹25 है। राशि क्या है?","o":["₹5000","₹8000","₹12500","₹10000"],"a":3,"e":"<b>हल:</b><br>चरण 1: 2 वर्ष के लिए सूत्र — CI − SI = P × (R/100)²<br>चरण 2: 25 = P × (5/100)² = P × 1/400<br>चरण 3: P = 25 × 400 = 10000<br>अतः उत्तर = <b>₹10000</b><br><b>ध्यान दें:</b> (5/100)² = 1/400 है, 1/20 नहीं — वर्ग करना न भूलें।"},
    {"q":"₹10000 पर 10% वार्षिक दर से 3 वर्ष के चक्रवृद्धि ब्याज और साधारण ब्याज का अंतर कितना है?","o":["₹300","₹310","₹331","₹210"],"a":1,"e":"<b>हल:</b><br>चरण 1: CI: A = 10000 × (1.1)³ = 10000 × 1.331 = 13310 → CI = ₹3310<br>चरण 2: SI = 10000 × 10 × 3 ÷ 100 = ₹3000<br>चरण 3: अंतर = 3310 − 3000 = 310<br>अतः उत्तर = <b>₹310</b><br><b>शॉर्टकट:</b> 3 वर्ष के लिए CI − SI = P(R/100)²(3 + R/100) = 10000 × 0.01 × 3.1 = ₹310<br><b>ध्यान दें:</b> ₹300 = 3 × P(R/100)² है (केवल 2 वर्ष वाला सूत्र तीन गुना); ₹331 पद (R/100)³ जोड़ना भूलने/गलत लगाने से आता है।"},
    {"q":"₹8000 पर 5% वार्षिक दर से 3 वर्ष के चक्रवृद्धि ब्याज और साधारण ब्याज का अंतर कितना होगा?","o":["₹60","₹61","₹62","₹63"],"a":1,"e":"<b>हल:</b><br>चरण 1: CI: A = 8000 × (1.05)³ = 8000 × 1.157625 = 9261 → CI = ₹1261<br>चरण 2: SI = 8000 × 5 × 3 ÷ 100 = ₹1200<br>चरण 3: अंतर = 1261 − 1200 = 61<br>अतः उत्तर = <b>₹61</b><br><b>शॉर्टकट:</b> P(R/100)²(3 + R/100) = 8000 × (1/400) × 3.05 = 20 × 3.05 = ₹61<br><b>ध्यान दें:</b> ₹60 = 3 × 20 है, जिसमें (R/100)³ वाला भाग छूट गया।"},
    {"q":"कोई राशि चक्रवृद्धि ब्याज पर 5 वर्ष में दोगुनी हो जाती है। उसी दर से वह कितने वर्ष में 8 गुनी होगी?","o":["20 वर्ष","10 वर्ष","15 वर्ष","40 वर्ष"],"a":2,"e":"<b>हल:</b><br>चरण 1: चक्रवृद्धि में राशि गुणात्मक रूप से बढ़ती है — 5 वर्ष में 2 गुना<br>चरण 2: अगले 5 वर्ष (कुल 10) में फिर 2 गुना → 4 गुना; अगले 5 (कुल 15) में → 8 गुना<br>चरण 3: 8 = 2³ → समय = 3 × 5 = 15 वर्ष<br>अतः उत्तर = <b>15 वर्ष</b><br><b>ध्यान दें:</b> 20 वर्ष (या 35) साधारण ब्याज की तरह रैखिक सोचने से आता है; 40 वर्ष = 8 × 5 गलत गुणा है।"},
    {"q":"चक्रवृद्धि ब्याज पर किसी राशि का 2 वर्ष बाद मिश्रधन ₹1210 तथा 3 वर्ष बाद ₹1331 है। वार्षिक दर क्या है?","o":["10%","11%","12%","9%"],"a":0,"e":"<b>हल:</b><br>चरण 1: लगातार दो वर्षों के मिश्रधन का अनुपात = (1 + R/100)<br>चरण 2: 1331 ÷ 1210 = 1.1<br>चरण 3: 1 + R/100 = 1.1 → R = 10<br>अतः उत्तर = <b>10%</b><br><b>शॉर्टकट:</b> तीसरे वर्ष का ब्याज = 1331 − 1210 = 121, जो 1210 का 10% है।"},
    {"q":"किसी राशि पर 2 वर्ष का साधारण ब्याज ₹400 तथा चक्रवृद्धि ब्याज ₹420 है। ब्याज दर क्या है?","o":["5%","20%","15%","10%"],"a":3,"e":"<b>हल:</b><br>चरण 1: 2 वर्ष का SI = 400 → 1 वर्ष का ब्याज = ₹200 (CI और SI में पहला वर्ष समान)<br>चरण 2: CI − SI = 420 − 400 = ₹20 — यह पहले वर्ष के ब्याज ₹200 पर दूसरे वर्ष का ब्याज है<br>चरण 3: R = 20 × 100 ÷ 200 = 10<br>अतः उत्तर = <b>10%</b><br><b>ध्यान दें:</b> 5% तब आता है जब 20 को 400 से भाग दें; अंतर केवल 1 वर्ष के ब्याज (200) पर बनता है।"},
    {"q":"₹8000 पर 10% वार्षिक दर से 1½ वर्ष का चक्रवृद्धि ब्याज कितना होगा, यदि ब्याज अर्धवार्षिक जुड़ता हो?","o":["₹1200","₹1261","₹1240","₹1280"],"a":1,"e":"<b>हल:</b><br>चरण 1: अर्धवार्षिक संयोजन → दर = 10/2 = 5% प्रति छमाही; 1½ वर्ष = 3 छमाही<br>चरण 2: A = 8000 × (1.05)³ = 8000 × 1.157625 = 9261<br>चरण 3: CI = 9261 − 8000 = 1261<br>अतः उत्तर = <b>₹1261</b><br><b>ध्यान दें:</b> ₹1200 साधारण ब्याज है; ₹1240 वार्षिक संयोजन (1 वर्ष 10% + आधा वर्ष 5%) से आता है।"},
    {"q":"किसी राशि पर 8% वार्षिक दर से 3 वर्ष का साधारण ब्याज, ₹4000 पर 10% वार्षिक दर से 2 वर्ष के चक्रवृद्धि ब्याज का आधा है। वह राशि क्या है?","o":["₹1750","₹1500","₹2000","₹1800"],"a":0,"e":"<b>हल:</b><br>चरण 1: ₹4000 पर 10% से 2 वर्ष का CI: A = 4000 × (1.1)² = 4840 → CI = ₹840<br>चरण 2: CI का आधा = 840 ÷ 2 = ₹420 = माँगी गई राशि का SI<br>चरण 3: P = 420 × 100 ÷ (8 × 3) = 42000 ÷ 24 = 1750<br>अतः उत्तर = <b>₹1750</b><br><b>ध्यान दें:</b> CI निकालते समय 4840 (मिश्रधन) नहीं, 840 (ब्याज) लें।"},
    {"q":"साधारण ब्याज पर कोई राशि 5 वर्ष में ₹9800 तथा 8 वर्ष में ₹12005 हो जाती है। ब्याज दर क्या है?","o":["10%","11%","12%","13%"],"a":2,"e":"<b>हल:</b><br>चरण 1: 3 वर्ष (8 − 5) का ब्याज = 12005 − 9800 = ₹2205<br>चरण 2: 1 वर्ष का ब्याज = 2205 ÷ 3 = ₹735<br>चरण 3: मूलधन = 9800 − 5 × 735 = 9800 − 3675 = ₹6125<br>चरण 4: R = 735 × 100 ÷ 6125 = 12<br>अतः उत्तर = <b>12%</b><br><b>ध्यान दें:</b> दर के लिए वार्षिक ब्याज को मूलधन (6125) से भाग दें, 9800 से नहीं।"},
    {"q":"₹2150 का ऋण, जो 4 वर्ष बाद देय है, 5% वार्षिक साधारण ब्याज पर किस समान वार्षिक किश्त से चुकेगा?","o":["₹520","₹480","₹500","₹537.50"],"a":2,"e":"<b>हल:</b><br>चरण 1: माना किश्त ₹x; 4 किश्तों पर क्रमशः 3, 2, 1, 0 वर्ष का ब्याज बनता है<br>चरण 2: कुल ब्याज = x × 5 × (3 + 2 + 1 + 0) ÷ 100 = 0.3x<br>चरण 3: 4x + 0.3x = 4.3x = 2150 → x = 500<br>अतः उत्तर = <b>₹500</b><br><b>शॉर्टकट:</b> किश्त = 100 इकाई मानें: 100 + 105 + 110 + 115 = 430 इकाई = 2150 → 100 इकाई = ₹500<br><b>ध्यान दें:</b> ₹537.50 = 2150 ÷ 4 है, जो ब्याज को अनदेखा करने से आता है।"},
    {"q":"₹6000 का ऋण, जो 5 वर्ष बाद देय है, 10% वार्षिक साधारण ब्याज पर किस समान वार्षिक किश्त से चुकेगा?","o":["₹1200","₹900","₹1100","₹1000"],"a":3,"e":"<b>हल:</b><br>चरण 1: माना किश्त ₹x; 5 किश्तों पर क्रमशः 4, 3, 2, 1, 0 वर्ष का ब्याज<br>चरण 2: कुल ब्याज = x × 10 × (4 + 3 + 2 + 1) ÷ 100 = x<br>चरण 3: 5x + x = 6x = 6000 → x = 1000<br>अतः उत्तर = <b>₹1000</b><br><b>शॉर्टकट:</b> x = 100A ÷ [100T + R × T(T − 1)/2] = 600000 ÷ (500 + 100) = ₹1000<br><b>ध्यान दें:</b> ₹1200 = 6000 ÷ 5 है, ब्याज को अनदेखा करके।"},
    {"q":"₹5040 का ऋण, जो 2 वर्ष बाद देय है, 10% वार्षिक साधारण ब्याज पर दो समान वार्षिक किश्तों में चुकाना है। प्रत्येक किश्त?","o":["₹2400","₹2520","₹2280","₹2500"],"a":0,"e":"<b>हल:</b><br>चरण 1: माना प्रत्येक किश्त ₹x। पहली किश्त 1 वर्ष बाद दी जाती है, जो देय तिथि तक 1 वर्ष ब्याज कमाती है; दूसरी किश्त पर ब्याज नहीं<br>चरण 2: पहली किश्त का मूल्य = x + x × 10 × 1 ÷ 100 = 1.1x<br>चरण 3: 1.1x + x = 2.1x = 5040 → x = 2400<br>अतः उत्तर = <b>₹2400</b><br><b>ध्यान दें:</b> ₹2520 = 5040 ÷ 2 है, ब्याज को अनदेखा करके।"},
    {"q":"यदि मूलधन, दर और समय तीनों को दोगुना कर दिया जाए तो साधारण ब्याज कितने गुना हो जाएगा?","o":["2 गुना","4 गुना","6 गुना","8 गुना"],"a":3,"e":"<b>हल:</b><br>चरण 1: सूत्र — SI = P × R × T ÷ 100; SI तीनों के गुणनफल के समानुपाती है<br>चरण 2: नया SI = (2P) × (2R) × (2T) ÷ 100 = 8 × PRT/100<br>अतः उत्तर = <b>8 गुना</b><br><b>ध्यान दें:</b> 6 गुना तब आता है जब गुणकों को जोड़ दें (2 + 2 + 2); गुणकों का गुणा होता है।"},
    {"q":"मिश्रधन किसके बराबर होता है?","o":["मूलधन − ब्याज","मूलधन + ब्याज","मूलधन × ब्याज","ब्याज ÷ मूलधन"],"a":1,"e":"<b>हल:</b><br>चरण 1: मिश्रधन (Amount) = वह कुल राशि जो अवधि के अंत में लौटाई जाती है<br>चरण 2: इसमें मूल राशि और उस पर बना ब्याज दोनों शामिल हैं → A = P + SI<br>अतः उत्तर = <b>मूलधन + ब्याज</b><br><b>ध्यान दें:</b> इसी से SI = A − P और P = A − SI भी निकलते हैं।"},
    {"q":"₹1800 का 10% वार्षिक दर से 3 वर्ष 4 महीने का साधारण ब्याज कितना होगा?","o":["₹540","₹580","₹600","₹640"],"a":2,"e":"<b>हल:</b><br>चरण 1: समय को वर्षों में बदलें — 3 वर्ष 4 महीने = 3 + 4/12 = 3 + 1/3 = 10/3 वर्ष<br>चरण 2: SI = 1800 × 10 × (10/3) ÷ 100<br>चरण 3: = 180000 ÷ 300 = 600<br>अतः उत्तर = <b>₹600</b><br><b>शॉर्टकट:</b> 1 वर्ष का ब्याज = 180 → 1 माह = 15 → 40 माह = ₹600<br><b>ध्यान दें:</b> ₹540 केवल 3 वर्ष का ब्याज है; 4 महीने का ₹60 जोड़ना न भूलें।"},
    {"q":"₹7300 का 10% वार्षिक दर से 73 दिन का साधारण ब्याज कितना होगा?","o":["₹146","₹150","₹73","₹160"],"a":0,"e":"<b>हल:</b><br>चरण 1: समय को वर्षों में बदलें — 73 दिन = 73/365 = 1/5 वर्ष<br>चरण 2: SI = 7300 × 10 × (1/5) ÷ 100<br>चरण 3: = 7300 × 2 ÷ 100 = 146<br>अतः उत्तर = <b>₹146</b><br><b>शॉर्टकट:</b> 1 वर्ष का ब्याज = 730 → 1/5 वर्ष = 730 ÷ 5 = ₹146<br><b>ध्यान दें:</b> दिनों को 365 से भाग दें (360 या 12 से नहीं)।"},
    {"q":"कौन-सी राशि 4% वार्षिक साधारण ब्याज पर 3 वर्ष में ₹1680 हो जाएगी?","o":["₹1450","₹1600","₹1550","₹1500"],"a":3,"e":"<b>हल:</b><br>चरण 1: 4% से 3 वर्ष का ब्याज = 12% → मिश्रधन = मूलधन का 100 + 12 = 112%<br>चरण 2: P × 112/100 = 1680<br>चरण 3: P = 1680 × 100 ÷ 112 = 1500<br>अतः उत्तर = <b>₹1500</b><br><b>ध्यान दें:</b> 1680 का 12% घटाने (1680 − 201.6) से गलत उत्तर आता है; ब्याज मूलधन पर बनता है, मिश्रधन पर नहीं।"},
    {"q":"कौन-सी राशि 6% वार्षिक साधारण ब्याज पर 4 वर्ष में ₹6200 हो जाएगी?","o":["₹5000","₹4800","₹5200","₹5500"],"a":0,"e":"<b>हल:</b><br>चरण 1: 6% से 4 वर्ष का ब्याज = 24% → मिश्रधन = मूलधन का 124%<br>चरण 2: P × 124/100 = 6200<br>चरण 3: P = 6200 × 100 ÷ 124 = 5000<br>अतः उत्तर = <b>₹5000</b><br><b>जाँच:</b> 5000 का 24% = 1200; 5000 + 1200 = 6200 ✓"},
    {"q":"किस वार्षिक दर से ₹1600, 5 वर्ष में साधारण ब्याज पर ₹2000 हो जाएँगे?","o":["4%","6%","5%","4.5%"],"a":2,"e":"<b>हल:</b><br>चरण 1: SI = A − P = 2000 − 1600 = ₹400<br>चरण 2: R = SI × 100 ÷ (P × T) = 400 × 100 ÷ (1600 × 5)<br>चरण 3: = 40000 ÷ 8000 = 5<br>अतः उत्तर = <b>5%</b><br><b>ध्यान दें:</b> दर निकालने में SI (400) लें, मिश्रधन (2000) नहीं।"},
    {"q":"₹2500, 6% वार्षिक साधारण ब्याज पर कितने वर्ष में ₹3250 हो जाएँगे?","o":["4 वर्ष","6 वर्ष","4.5 वर्ष","5 वर्ष"],"a":3,"e":"<b>हल:</b><br>चरण 1: SI = A − P = 3250 − 2500 = ₹750<br>चरण 2: T = SI × 100 ÷ (P × R) = 750 × 100 ÷ (2500 × 6)<br>चरण 3: = 75000 ÷ 15000 = 5<br>अतः उत्तर = <b>5 वर्ष</b><br><b>शॉर्टकट:</b> 1 वर्ष का ब्याज = 2500 का 6% = 150 → 750 ÷ 150 = 5 वर्ष"},
    {"q":"ब्याज दर 10% से घटकर 8% हो जाने पर किसी व्यक्ति की वार्षिक आय ₹60 कम हो जाती है। उसका मूलधन कितना है?","o":["₹3000","₹2400","₹6000","₹1500"],"a":0,"e":"<b>हल:</b><br>चरण 1: दर में कमी = 10% − 8% = 2%; इससे 1 वर्ष की आय ₹60 घटी<br>चरण 2: P का 2% = 60<br>चरण 3: P = 60 × 100 ÷ 2 = 3000<br>अतः उत्तर = <b>₹3000</b><br><b>ध्यान दें:</b> ₹6000 = 60 × 100 ÷ 1 गलत है, और ₹600/₹750 जैसे उत्तर 60 को 10% या 8% मानने से आते हैं।"},
    {"q":"एक व्यक्ति अपनी पूँजी का 1/3 भाग 3%, 1/6 भाग 6% और शेष 8% वार्षिक साधारण ब्याज पर देता है। उसकी वार्षिक आय ₹600 है। कुल पूँजी?","o":["₹12000","₹9000","₹10000","₹8000"],"a":2,"e":"<b>हल:</b><br>चरण 1: शेष भाग = 1 − 1/3 − 1/6 = 1/2<br>चरण 2: औसत (भारित) दर = (1/3) × 3 + (1/6) × 6 + (1/2) × 8 = 1 + 1 + 4 = 6%<br>चरण 3: पूँजी का 6% = 600 → पूँजी = 600 × 100 ÷ 6 = 10000<br>अतः उत्तर = <b>₹10000</b><br><b>जाँच:</b> 10000 में से 3333.33 पर 3% = 100, 1666.67 पर 6% = 100, 5000 पर 8% = 400; कुल = ₹600 ✓"},
    {"q":"एक ही राशि पर 5% की दर से 2 वर्ष तथा 4% की दर से 3 वर्ष के साधारण ब्याज का अनुपात क्या है?","o":["6 : 5","5 : 6","4 : 3","2 : 3"],"a":1,"e":"<b>हल:</b><br>चरण 1: मूलधन P समान है, अतः SI ∝ R × T<br>चरण 2: पहला SI ∝ 5 × 2 = 10; दूसरा SI ∝ 4 × 3 = 12<br>चरण 3: अनुपात = 10 : 12 = 5 : 6<br>अतः उत्तर = <b>5 : 6</b><br><b>ध्यान दें:</b> 6 : 5 उल्टा क्रम है — प्रश्न में पहले 5% वाला ब्याज है।"},
    {"q":"₹2000 को 5% और ₹3000 को 6% वार्षिक साधारण ब्याज पर 2 वर्ष के लिए दिया गया। पूरी राशि पर औसत ब्याज दर क्या है?","o":["5.5%","5.4%","5.6%","5.8%"],"a":2,"e":"<b>हल:</b><br>चरण 1: ₹2000 पर 5% से 2 वर्ष का SI = 2000 × 5 × 2 ÷ 100 = ₹200<br>चरण 2: ₹3000 पर 6% से 2 वर्ष का SI = 3000 × 6 × 2 ÷ 100 = ₹360<br>चरण 3: कुल ब्याज = 560; कुल राशि = 5000<br>चरण 4: औसत दर = 560 × 100 ÷ (5000 × 2) = 5.6<br>अतः उत्तर = <b>5.6%</b><br><b>शॉर्टकट:</b> भारित औसत = (2 × 5 + 3 × 6) ÷ 5 = 28 ÷ 5 = 5.6%<br><b>ध्यान दें:</b> 5.5% दरों का सीधा औसत है; राशियाँ असमान हैं, इसलिए भारित औसत लें।"},
    {"q":"दो बराबर राशियाँ समान समय के लिए 8% और 6% वार्षिक साधारण ब्याज पर दी गईं। 3 वर्ष बाद ब्याजों का अंतर ₹120 है। प्रत्येक राशि?","o":["₹2000","₹1500","₹2500","₹3000"],"a":0,"e":"<b>हल:</b><br>चरण 1: समान राशि P पर दरों का अंतर = 8% − 6% = 2% वार्षिक<br>चरण 2: 3 वर्ष में ब्याज का अंतर = P × 2 × 3 ÷ 100 = 6P/100 = 120<br>चरण 3: P = 120 × 100 ÷ 6 = 2000<br>अतः उत्तर = <b>₹2000</b><br><b>ध्यान दें:</b> ₹3000 तब आता है जब 3 वर्ष से गुणा न करके 120 को 2 वर्ष में बाँट दें; ₹6000 तब जब समय को अनदेखा करें।"},
    {"q":"साधारण ब्याज पर कोई राशि 10 वर्ष में दोगुनी होती है। वह कितने वर्ष में 2.5 गुनी होगी?","o":["12 वर्ष","15 वर्ष","20 वर्ष","25 वर्ष"],"a":1,"e":"<b>हल:</b><br>चरण 1: दोगुना → ब्याज = P (मूलधन का 100%), जो 10 वर्ष में मिलता है → वार्षिक दर = 10%<br>चरण 2: 2.5 गुना → ब्याज = 2.5P − P = 1.5P (150%)<br>चरण 3: समय = 150 ÷ 10 = 15 वर्ष<br>अतः उत्तर = <b>15 वर्ष</b><br><b>शॉर्टकट:</b> T₂ = T₁ × (n₂ − 1)/(n₁ − 1) = 10 × 1.5/1 = 15 वर्ष<br><b>ध्यान दें:</b> 25 वर्ष = 10 × 2.5 है, जो मिश्रधन को ब्याज मानने की भूल से आता है।"},
    {"q":"6.25% वार्षिक साधारण ब्याज पर कोई राशि कितने वर्ष में दोगुनी होगी?","o":["12 वर्ष","14 वर्ष","15 वर्ष","16 वर्ष"],"a":3,"e":"<b>हल:</b><br>चरण 1: दोगुना → ब्याज = मूलधन → R × T = 100<br>चरण 2: T = 100 ÷ 6.25<br>चरण 3: = 16<br>अतः उत्तर = <b>16 वर्ष</b><br><b>शॉर्टकट:</b> 6.25% = 1/16 → 16 वर्ष में 100% ब्याज।"},
    {"q":"साधारण ब्याज पर कोई राशि 12 वर्ष में तिगुनी हो जाती है। वार्षिक दर क्या है?","o":["16%","15%","16 2/3%","18%"],"a":2,"e":"<b>हल:</b><br>चरण 1: तिगुना → ब्याज = 3P − P = 2P = मूलधन का 200%<br>चरण 2: R × 12 = 200 → R = 200/12 = 50/3<br>चरण 3: 50/3 = 16 2/3<br>अतः उत्तर = <b>16 2/3%</b><br><b>ध्यान दें:</b> 25% तब आता है जब ब्याज को 3P (300%) मान लें।"},
    {"q":"किस वार्षिक दर से 6 वर्ष में किसी राशि का साधारण ब्याज उस राशि का 3/8 हो जाएगा?","o":["6%","6.5%","7.5%","6.25%"],"a":3,"e":"<b>हल:</b><br>चरण 1: SI = P का 3/8 → प्रतिशत में = 3/8 × 100 = 37.5%<br>चरण 2: R × T = 37.5 → R × 6 = 37.5<br>चरण 3: R = 37.5 ÷ 6 = 6.25<br>अतः उत्तर = <b>6.25%</b><br><b>ध्यान दें:</b> 3/8 को सीधे 6 से भाग देकर प्रतिशत में बदलना न भूलें।"},
    {"q":"किसी राशि को 3 वर्ष के लिए साधारण ब्याज पर दिया गया। यदि दर 3% अधिक होती तो ₹72 अधिक मिलते। राशि क्या है?","o":["₹800","₹2400","₹720","₹600"],"a":0,"e":"<b>हल:</b><br>चरण 1: दर 3% बढ़ने पर अतिरिक्त ब्याज = P × 3 × 3 ÷ 100 = 9P/100<br>चरण 2: 9P/100 = 72<br>चरण 3: P = 7200 ÷ 9 = 800<br>अतः उत्तर = <b>₹800</b><br><b>ध्यान दें:</b> ₹2400 तब आता है जब समय (3 वर्ष) से गुणा भूल जाएँ (72 × 100 ÷ 3)।"},
    {"q":"₹5000 पर ₹1 प्रति सैकड़ा प्रति माह की दर से 2 वर्ष का साधारण ब्याज कितना होगा?","o":["₹100","₹120","₹1000","₹1200"],"a":3,"e":"<b>हल:</b><br>चरण 1: ₹1 प्रति सैकड़ा प्रति माह = ₹100 पर हर माह ₹1 = 1% मासिक = 12% वार्षिक<br>चरण 2: SI = 5000 × 12 × 2 ÷ 100<br>चरण 3: = 1200<br>अतः उत्तर = <b>₹1200</b><br><b>शॉर्टकट:</b> 2 वर्ष = 24 माह × 1% = 24% → 5000 का 24% = ₹1200<br><b>ध्यान दें:</b> ₹100 या ₹120 मासिक दर को वार्षिक मानने से आता है।"},
    {"q":"₹1200 का 4 वर्ष का तथा ₹1500 का 3 वर्ष का साधारण ब्याज, एक ही दर से, मिलाकर ₹558 है। दर क्या है?","o":["5%","6%","7%","8%"],"a":1,"e":"<b>हल:</b><br>चरण 1: माना दर R%; पहला SI = 1200 × 4 × R ÷ 100 = 48R; दूसरा SI = 1500 × 3 × R ÷ 100 = 45R<br>चरण 2: 48R + 45R = 93R = 558<br>चरण 3: R = 558 ÷ 93 = 6<br>अतः उत्तर = <b>6%</b><br><b>जाँच:</b> 288 + 270 = 558 ✓"},
    {"q":"कोई राशि साधारण ब्याज पर 3 वर्ष में ₹1120 तथा 5 वर्ष में ₹1200 हो जाती है। मूलधन क्या है?","o":["₹960","₹1040","₹1000","₹920"],"a":2,"e":"<b>हल:</b><br>चरण 1: 2 वर्ष (5 − 3) का ब्याज = 1200 − 1120 = ₹80<br>चरण 2: 1 वर्ष का ब्याज = 80 ÷ 2 = ₹40<br>चरण 3: मूलधन = 1120 − 3 वर्ष का ब्याज = 1120 − 120 = 1000<br>अतः उत्तर = <b>₹1000</b><br><b>ध्यान दें:</b> ₹1040 तब आता है जब केवल 2 वर्ष का ब्याज (80) घटाएँ।"},
    {"q":"₹16000 पर 20% वार्षिक दर से 6 महीने का चक्रवृद्धि ब्याज, जब ब्याज त्रैमासिक जुड़ता हो, कितना होगा?","o":["₹1600","₹1640","₹1680","₹1620"],"a":1,"e":"<b>हल:</b><br>चरण 1: त्रैमासिक संयोजन → दर = 20/4 = 5% प्रति तिमाही; 6 महीने = 2 तिमाही<br>चरण 2: A = 16000 × (1.05)² = 16000 × 1.1025 = 17640<br>चरण 3: CI = 17640 − 16000 = 1640<br>अतः उत्तर = <b>₹1640</b><br><b>शॉर्टकट:</b> प्रभावी दर = 5 + 5 + 0.25 = 10.25% → 16000 का 10.25% = ₹1640<br><b>ध्यान दें:</b> ₹1600 साधारण ब्याज है; ₹1680 तब आता है जब 6 महीने के लिए पूरी 10% अर्धवार्षिक दर (₹1600) पर अलग से ₹80 जोड़ दें — तिमाही दर 5% ही लें।"},
    {"q":"साधारण ब्याज में हर वर्ष का ब्याज —","o":["बढ़ता जाता है","घटता जाता है","बराबर रहता है","पहले बढ़ता फिर घटता है"],"a":2,"e":"<b>हल:</b><br>चरण 1: साधारण ब्याज हर वर्ष केवल मूल मूलधन P पर लगता है, पिछले ब्याज पर नहीं<br>चरण 2: अतः हर वर्ष का ब्याज = P × R ÷ 100 = स्थिर<br>अतः उत्तर = <b>बराबर रहता है</b><br><b>ध्यान दें:</b> \"बढ़ता जाता है\" चक्रवृद्धि ब्याज का गुण है, जहाँ ब्याज पर भी ब्याज लगता है।"},
    {"q":"₹6000 पर 10% वार्षिक दर से पहले वर्ष के साधारण ब्याज और चक्रवृद्धि ब्याज (वार्षिक संयोजन) का अंतर कितना है?","o":["₹0","₹60","₹6","₹600"],"a":0,"e":"<b>हल:</b><br>चरण 1: पहले वर्ष SI = 6000 × 10 ÷ 100 = ₹600<br>चरण 2: पहले वर्ष CI भी मूलधन ₹6000 पर ही = ₹600 (अभी कोई ब्याज जुड़ा नहीं है)<br>चरण 3: अंतर = 600 − 600 = 0<br>अतः उत्तर = <b>₹0</b><br><b>ध्यान दें:</b> ₹60 दूसरे वर्ष का अंतर (600 का 10%) है, पहले वर्ष का नहीं।"},
    {"q":"किसी राशि पर 2 वर्ष का साधारण ब्याज ₹1200 तथा चक्रवृद्धि ब्याज ₹1260 है। राशि क्या है?","o":["₹5000","₹6000","₹6300","₹7200"],"a":1,"e":"<b>हल:</b><br>चरण 1: 2 वर्ष का SI = 1200 → 1 वर्ष का ब्याज = ₹600<br>चरण 2: CI − SI = 1260 − 1200 = ₹60 = पहले वर्ष के ब्याज ₹600 पर 1 वर्ष का ब्याज → R = 60 × 100 ÷ 600 = 10%<br>चरण 3: P = 600 × 100 ÷ 10 = 6000<br>अतः उत्तर = <b>₹6000</b><br><b>शॉर्टकट:</b> P = (SI/2)² ÷ (CI − SI) = 600² ÷ 60 = ₹6000"},
    {"q":"₹15000 का कुछ भाग 6% तथा शेष 10% वार्षिक साधारण ब्याज पर 2 वर्ष के लिए दिया। कुल ब्याज ₹2400 मिला। 10% पर दी गई राशि?","o":["₹6000","₹9000","₹5000","₹7500"],"a":3,"e":"<b>हल:</b><br>चरण 1: औसत दर = कुल ब्याज × 100 ÷ (कुल राशि × समय) = 2400 × 100 ÷ (15000 × 2) = 8%<br>चरण 2: मिश्रण नियम: 6% भाग : 10% भाग = (10 − 8) : (8 − 6) = 2 : 2 = 1 : 1<br>चरण 3: 10% पर राशि = 15000 × 1/2 = 7500<br>अतः उत्तर = <b>₹7500</b><br><b>जाँच:</b> 7500 × 6 × 2/100 + 7500 × 10 × 2/100 = 900 + 1500 = 2400 ✓"},
    {"q":"₹7500 का 4% वार्षिक दर से 2 वर्ष का साधारण ब्याज कितना है?","o":["₹500","₹550","₹600","₹650"],"a":2,"e":"<b>हल:</b><br>चरण 1: सूत्र — SI = P × R × T ÷ 100<br>चरण 2: SI = 7500 × 4 × 2 ÷ 100 = 75 × 8 = 600<br>अतः उत्तर = <b>₹600</b>"},
    {"q":"₹3650 का 8% वार्षिक दर से 15 जनवरी से 29 मार्च (साधारण वर्ष) तक का साधारण ब्याज कितना होगा?","o":["₹56","₹58.40","₹59.20","₹62.40"],"a":1,"e":"<b>हल:</b><br>चरण 1: दिन गिनें (जमा का पहला दिन छोड़कर, अंतिम दिन गिनकर): जनवरी 31 − 15 = 16, फ़रवरी 28 (साधारण वर्ष), मार्च 29 → कुल 73 दिन<br>चरण 2: T = 73/365 = 1/5 वर्ष<br>चरण 3: SI = 3650 × 8 × (1/5) ÷ 100 = 3650 × 8 ÷ 500 = 58.40<br>अतः उत्तर = <b>₹58.40</b><br><b>ध्यान दें:</b> ₹59.20 तब आता है जब 74 दिन गिनें (पहला और अंतिम दोनों दिन) — परंपरा से केवल एक ही दिन गिना जाता है।"},
    {"q":"कोई राशि साधारण ब्याज पर 4 वर्ष में ₹1440 हो जाती है। यदि दर 2% अधिक होती तो वह ₹1536 हो जाती। मूल वार्षिक दर क्या थी?","o":["4%","6%","5%","8%"],"a":2,"e":"<b>हल:</b><br>चरण 1: दर 2% बढ़ने पर अतिरिक्त मिश्रधन = 1536 − 1440 = ₹96 = P × 2 × 4 ÷ 100<br>चरण 2: 8P/100 = 96 → P = 1200<br>चरण 3: मूल SI = 1440 − 1200 = ₹240<br>चरण 4: R = 240 × 100 ÷ (1200 × 4) = 5<br>अतः उत्तर = <b>5%</b><br><b>ध्यान दें:</b> 7% बढ़ी हुई दर है; प्रश्न मूल दर पूछता है।"},
    {"q":"एक व्यक्ति हर माह की शुरुआत में ₹100 आवर्ती जमा (RD) में 12 माह तक जमा करता है। 12% वार्षिक साधारण ब्याज पर वर्ष के अंत में कुल ब्याज कितना मिलेगा?","o":["₹78","₹72","₹144","₹84"],"a":0,"e":"<b>हल:</b><br>चरण 1: पहली ₹100 की किश्त 12 माह, दूसरी 11 माह, …, अंतिम 1 माह ब्याज कमाती है<br>चरण 2: कुल \"रुपया-माह\" = 100 × (12 + 11 + … + 1) = 100 × 78 = 7800 (क्योंकि 1 से 12 का योग = 12 × 13/2 = 78)<br>चरण 3: मासिक दर = 12/12 = 1% → ब्याज = 7800 × 1/100 = 78<br>अतः उत्तर = <b>₹78</b><br><b>शॉर्टकट:</b> RD ब्याज = P × n(n + 1)/2 × R/(12 × 100) = 100 × 78 × 12/1200 = ₹78<br><b>ध्यान दें:</b> ₹144 तब आता है जब मानें कि पूरे ₹1200 पर पूरे वर्ष ब्याज मिला; ₹72 तब जब 12 × 11/2 = 66 लें।"},
    {"q":"किसी राशि का 4% वार्षिक साधारण ब्याज पर 5 वर्ष का मिश्रधन, उसी राशि के 5% वार्षिक दर पर 3 वर्ष के मिश्रधन से ₹100 अधिक है। राशि क्या है?","o":["₹1500","₹2500","₹4000","₹2000"],"a":3,"e":"<b>हल:</b><br>चरण 1: 4% से 5 वर्ष → ब्याज 20% → मिश्रधन = 1.20P<br>चरण 2: 5% से 3 वर्ष → ब्याज 15% → मिश्रधन = 1.15P<br>चरण 3: अंतर = 1.20P − 1.15P = 0.05P = 100 → P = 2000<br>अतः उत्तर = <b>₹2000</b><br><b>ध्यान दें:</b> मिश्रधनों का अंतर = ब्याजों का अंतर, क्योंकि मूलधन समान है।"},
    {"q":"A ने ₹8000, 6% वार्षिक साधारण ब्याज पर उधार लिए और तुरंत यही राशि 8% वार्षिक चक्रवृद्धि ब्याज (वार्षिक संयोजन) पर 2 वर्ष के लिए उधार दे दी। 2 वर्ष में A का लाभ कितना है?","o":["₹320","₹331.20","₹371.20","₹396.80"],"a":2,"e":"<b>हल:</b><br>चरण 1: A को मिलने वाला CI = 8000 × [(1.08)² − 1] = 8000 × (1.1664 − 1) = 8000 × 0.1664 = ₹1331.20<br>चरण 2: A को देना पड़ने वाला SI = 8000 × 6 × 2 ÷ 100 = ₹960<br>चरण 3: लाभ = 1331.20 − 960 = 371.20<br>अतः उत्तर = <b>₹371.20</b><br><b>ध्यान दें:</b> ₹320 = 8000 × 2% × 2 है, जो दोनों को साधारण ब्याज मानने से आता है; ₹331.20 तब जब CI से ₹1000 घटा दें।"},
    {"q":"₹800 का 2 पैसे प्रति रुपया प्रति माह की दर से 6 महीने का साधारण ब्याज कितना होगा?","o":["₹96","₹16","₹192","₹48"],"a":0,"e":"<b>हल:</b><br>चरण 1: 2 पैसे प्रति ₹1 प्रति माह = ₹100 पर हर माह ₹2 = 2% मासिक<br>चरण 2: 6 महीने में कुल = 2 × 6 = 12%<br>चरण 3: SI = 800 × 12 ÷ 100 = 96<br>अतः उत्तर = <b>₹96</b><br><b>ध्यान दें:</b> ₹16 केवल 1 माह का ब्याज है; ₹192 तब आता है जब 6 को 12 माह मानें।"},
    {"q":"साधारण ब्याज पर कोई राशि 8 वर्ष में दोगुनी हो जाती है। उसी दर से ₹5000 का 3 वर्ष का साधारण ब्याज कितना होगा?","o":["₹1500","₹2000","₹1250","₹1875"],"a":3,"e":"<b>हल:</b><br>चरण 1: 8 वर्ष में दोगुना → R × 8 = 100 → R = 12.5%<br>चरण 2: SI = 5000 × 12.5 × 3 ÷ 100<br>चरण 3: = 50 × 37.5 = 1875<br>अतः उत्तर = <b>₹1875</b><br><b>शॉर्टकट:</b> 8 वर्ष में ब्याज = 5000 → 3 वर्ष में = 5000 × 3/8 = ₹1875"},
    {"q":"किसी राशि पर 6% वार्षिक दर से 4 वर्ष का साधारण ब्याज, उसी राशि पर 8% वार्षिक दर से कितने वर्ष के साधारण ब्याज के बराबर होगा?","o":["2 वर्ष","3 वर्ष","4 वर्ष","5 वर्ष"],"a":1,"e":"<b>हल:</b><br>चरण 1: समान मूलधन पर SI समान होने के लिए R × T समान होना चाहिए<br>चरण 2: 6 × 4 = 8 × T → 24 = 8T<br>चरण 3: T = 3<br>अतः उत्तर = <b>3 वर्ष</b><br><b>ध्यान दें:</b> दर बढ़ने पर समय घटता है (व्युत्क्रम संबंध)।"},
    {"q":"किसी राशि पर 3 वर्ष का साधारण ब्याज ₹900 है। यदि दर 4% अधिक होती तो उतना ही ब्याज 2 वर्ष में मिल जाता। मूलधन क्या है?","o":["₹3750","₹3000","₹4500","₹3600"],"a":0,"e":"<b>हल:</b><br>चरण 1: माना मूल दर R%। समान ब्याज के लिए R × T समान: R × 3 = (R + 4) × 2<br>चरण 2: 3R = 2R + 8 → R = 8%<br>चरण 3: P = 900 × 100 ÷ (8 × 3) = 90000 ÷ 24 = 3750<br>अतः उत्तर = <b>₹3750</b><br><b>जाँच:</b> 3750 × 12% × 2 = 900 ✓"},
    {"q":"समान दर पर ₹2000 के 6 वर्ष के साधारण ब्याज और ₹3000 के 4 वर्ष के साधारण ब्याज का अनुपात क्या है?","o":["2 : 3","3 : 2","1 : 1","4 : 9"],"a":2,"e":"<b>हल:</b><br>चरण 1: दर समान है, अतः SI ∝ P × T<br>चरण 2: पहला = 2000 × 6 = 12000; दूसरा = 3000 × 4 = 12000<br>चरण 3: अनुपात = 12000 : 12000 = 1 : 1<br>अतः उत्तर = <b>1 : 1</b><br><b>ध्यान दें:</b> 2 : 3 केवल मूलधनों का अनुपात है; समय को भी गुणा करें।"},
    {"q":"साधारण ब्याज पर किसी राशि के 4 वर्ष बाद के मिश्रधन और मूलधन का अनुपात 6 : 5 है। वार्षिक दर क्या है?","o":["4%","6%","20%","5%"],"a":3,"e":"<b>हल:</b><br>चरण 1: A : P = 6 : 5 → माना P = 5, A = 6 → SI = 1<br>चरण 2: SI/P = 1/5 = 20% (4 वर्ष में)<br>चरण 3: R = 20 ÷ 4 = 5<br>अतः उत्तर = <b>5%</b><br><b>ध्यान दें:</b> 20% चार वर्ष का कुल ब्याज है, वार्षिक दर नहीं।"},
    {"q":"एक टीवी नकद ₹20000 में मिलता है, अथवा ₹5000 तुरंत देकर तथा 1 वर्ष बाद ₹15900 देकर। किस्त योजना में साधारण ब्याज की वार्षिक दर क्या है?","o":["4.5%","6%","5%","6.5%"],"a":1,"e":"<b>हल:</b><br>चरण 1: किस्त योजना में वास्तव में उधार ली गई राशि = 20000 − 5000 = ₹15000 (तुरंत दिए ₹5000 पर ब्याज नहीं)<br>चरण 2: 1 वर्ष बाद दिए ₹15900 में ब्याज = 15900 − 15000 = ₹900<br>चरण 3: R = 900 × 100 ÷ (15000 × 1) = 6<br>अतः उत्तर = <b>6%</b><br><b>ध्यान दें:</b> 4.5% तब आता है जब ब्याज ₹900 को पूरे ₹20000 पर मानें।"},
    {"q":"किसी राशि पर 6% वार्षिक दर से 5 वर्ष का साधारण ब्याज, उसी राशि के 4 वर्ष के साधारण ब्याज से ₹150 अधिक है। राशि क्या है?","o":["₹1500","₹2500","₹3000","₹2000"],"a":1,"e":"<b>हल:</b><br>चरण 1: 5 वर्ष के SI − 4 वर्ष के SI = 1 वर्ष का SI = ₹150<br>चरण 2: P का 6% = 150<br>चरण 3: P = 150 × 100 ÷ 6 = 2500<br>अतः उत्तर = <b>₹2500</b>"},
    {"q":"2 वर्ष बाद देय ₹1100 का 5% वार्षिक साधारण ब्याज पर वर्तमान मूल्य (Present Worth) कितना है?","o":["₹990","₹1045","₹1050","₹1000"],"a":3,"e":"<b>हल:</b><br>चरण 1: वर्तमान मूल्य (PW) वह राशि है जो आज जमा करने पर 2 वर्ष में ब्याज सहित ₹1100 हो जाए<br>चरण 2: 5% से 2 वर्ष → मिश्रधन = PW का 110% → PW × 110/100 = 1100<br>चरण 3: PW = 1100 × 100 ÷ 110 = 1000<br>अतः उत्तर = <b>₹1000</b><br><b>ध्यान दें:</b> ₹990 तब आता है जब 1100 में से उसका 10% घटा दें; ब्याज वर्तमान मूल्य पर लगता है, देय राशि पर नहीं।"},
    {"q":"3 वर्ष बाद देय ₹2360 पर 6% वार्षिक साधारण ब्याज की दर से वास्तविक बट्टा (True Discount) कितना है?","o":["₹360","₹424.80","₹400","₹320"],"a":0,"e":"<b>हल:</b><br>चरण 1: 6% से 3 वर्ष → ब्याज 18% → देय राशि = वर्तमान मूल्य (PW) का 118%<br>चरण 2: PW = 2360 × 100 ÷ 118 = 2000<br>चरण 3: वास्तविक बट्टा (TD) = देय राशि − PW = 2360 − 2000 = 360<br>अतः उत्तर = <b>₹360</b> (= ₹2000 पर 3 वर्ष का ब्याज)<br><b>शॉर्टकट:</b> TD = A × RT ÷ (100 + RT) = 2360 × 18/118 = ₹360<br><b>ध्यान दें:</b> ₹424.80 = 2360 का 18% है — यह बैंकर का बट्टा है, वास्तविक बट्टा नहीं।"},
    {"q":"₹x का 5% वार्षिक दर से 4 वर्ष का साधारण ब्याज, ₹y के 8% वार्षिक दर से 5 वर्ष के साधारण ब्याज के बराबर है। x : y कितना है?","o":["1 : 2","5 : 8","2 : 1","8 : 5"],"a":2,"e":"<b>हल:</b><br>चरण 1: ₹x पर SI = x × 5 × 4 ÷ 100 = 20x/100; ₹y पर SI = y × 8 × 5 ÷ 100 = 40y/100<br>चरण 2: 20x = 40y → x = 2y<br>चरण 3: x : y = 2 : 1<br>अतः उत्तर = <b>2 : 1</b><br><b>ध्यान दें:</b> 1 : 2 उल्टा अनुपात है — कम R × T वाली राशि बड़ी होगी।"},
    {"q":"₹600 पर 5% वार्षिक दर से कितने वर्ष में उतना ही साधारण ब्याज मिलेगा जितना ₹1000 पर 6% वार्षिक दर से 4 वर्ष में मिलता है?","o":["6 वर्ष","7 वर्ष","8 वर्ष","10 वर्ष"],"a":2,"e":"<b>हल:</b><br>चरण 1: ₹1000 पर 6% से 4 वर्ष का SI = 1000 × 6 × 4 ÷ 100 = ₹240<br>चरण 2: ₹600 पर 5% से T वर्ष का SI = 600 × 5 × T ÷ 100 = 30T<br>चरण 3: 30T = 240 → T = 8<br>अतः उत्तर = <b>8 वर्ष</b>"},
    {"q":"एक व्यक्ति ने 10% वार्षिक साधारण ब्याज पर ₹5000 जमा किए और 2 वर्ष बाद ₹1000 और जमा किए। पहली जमा के 5 वर्ष पूरे होने पर उसे कुल कितना ब्याज मिलेगा?","o":["₹3000","₹2800","₹2700","₹2500"],"a":1,"e":"<b>हल:</b><br>चरण 1: ₹5000 पूरे 5 वर्ष जमा रहे → SI = 5000 × 10 × 5 ÷ 100 = ₹2500<br>चरण 2: ₹1000, 2 वर्ष बाद जमा हुए → केवल 5 − 2 = 3 वर्ष → SI = 1000 × 10 × 3 ÷ 100 = ₹300<br>चरण 3: कुल ब्याज = 2500 + 300 = 2800<br>अतः उत्तर = <b>₹2800</b><br><b>ध्यान दें:</b> ₹3000 तब आता है जब ₹1000 पर भी 5 वर्ष का ब्याज लगा दें।"},
    {"q":"किसी राशि पर 8% वार्षिक दर से 5 वर्ष का साधारण ब्याज, उस राशि से ₹1200 कम है। राशि क्या है?","o":["₹3000","₹1500","₹2400","₹2000"],"a":3,"e":"<b>हल:</b><br>चरण 1: SI = P × 8 × 5 ÷ 100 = 40% = 0.4P<br>चरण 2: P − SI = 1200 → P − 0.4P = 0.6P = 1200<br>चरण 3: P = 1200 ÷ 0.6 = 2000<br>अतः उत्तर = <b>₹2000</b><br><b>ध्यान दें:</b> ₹3000 तब आता है जब 1200 को SI (0.4P) मान लें।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. साधारण ब्याज पर मिश्रधन प्रति वर्ष समान राशि से बढ़ता है।<br>2. वार्षिक संयोजन पर पहले वर्ष का चक्रवृद्धि ब्याज, साधारण ब्याज से अधिक होता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"<b>हल:</b><br>कथन 1: साधारण ब्याज में हर वर्ष ब्याज = P × R ÷ 100 (स्थिर), अतः मिश्रधन हर वर्ष समान राशि से बढ़ता है — <b>सही</b><br>कथन 2: वार्षिक संयोजन में पहले वर्ष ब्याज मूलधन पर ही लगता है, अतः पहले वर्ष CI = SI, अधिक नहीं — <b>गलत</b><br>अतः उत्तर = <b>केवल 1</b><br><b>ध्यान दें:</b> CI, SI से दूसरे वर्ष से अधिक होना शुरू होता है (अर्धवार्षिक आदि संयोजन में पहले वर्ष भी अधिक हो सकता है)।"},
    {"q":"अभिकथन (A): साधारण ब्याज पर कोई राशि 10 वर्ष में दोगुनी होती है तो वह 20 वर्ष में तिगुनी हो जाएगी।<br>कारण (R): साधारण ब्याज में प्रति वर्ष ब्याज केवल मूल मूलधन पर लगता है, अतः हर वर्ष समान होता है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"<b>हल:</b><br>अभिकथन (A): 10 वर्ष में दोगुना → 10 वर्ष का ब्याज = P → 20 वर्ष का ब्याज = 2P → मिश्रधन = P + 2P = 3P (तिगुना) — <b>सही</b><br>कारण (R): साधारण ब्याज केवल मूल मूलधन पर लगता है, अतः हर वर्ष समान — <b>सही</b><br>व्याख्या: हर वर्ष ब्याज समान होने से ही 20 वर्ष का ब्याज, 10 वर्ष के ब्याज का ठीक दोगुना है — R, A की सही व्याख्या है<br>अतः उत्तर = <b>A और R दोनों सही हैं तथा R, A की सही व्याख्या है</b><br><b>ध्यान दें:</b> चक्रवृद्धि ब्याज में 20 वर्ष में राशि 4 गुनी होती, तिगुनी नहीं।"},
    {"q":"सूची-I (साधारण ब्याज की वार्षिक दर) को सूची-II (धन दोगुना होने का समय) से सुमेलित कीजिए —<br>(A) 5% (B) 8% (C) 12.5% (D) 20%<br>1. 5 वर्ष 2. 8 वर्ष 3. 12.5 वर्ष 4. 20 वर्ष","o":["A-1, B-2, C-3, D-4","A-4, B-2, C-3, D-1","A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1"],"a":3,"e":"<b>हल:</b><br>चरण 1: दोगुना → ब्याज = P → R × T = 100 → T = 100/R<br>चरण 2: (A) 5% → 100/5 = 20 वर्ष → 4<br>(B) 8% → 100/8 = 12.5 वर्ष → 3<br>(C) 12.5% → 100/12.5 = 8 वर्ष → 2<br>(D) 20% → 100/20 = 5 वर्ष → 1<br>अतः उत्तर = <b>A-4, B-3, C-2, D-1</b><br><b>ध्यान दें:</b> A-1, B-2, C-3, D-4 सीधा क्रम है, पर दर और समय व्युत्क्रमानुपाती हैं — अधिक दर, कम समय।"},
    {"q":"किसी राशि पर r% वार्षिक दर से 3 वर्ष का साधारण ब्याज, उसी राशि पर (r − 2)% वार्षिक दर से 5 वर्ष के साधारण ब्याज के बराबर है। r का मान क्या है?","o":["4","5","6","7.5"],"a":1,"e":"<b>हल:</b><br>चरण 1: समान राशि पर SI बराबर → R × T बराबर<br>चरण 2: r × 3 = (r − 2) × 5 → 3r = 5r − 10<br>चरण 3: 2r = 10 → r = 5<br>अतः उत्तर = <b>5</b><br><b>जाँच:</b> 5 × 3 = 15 और 3 × 5 = 15 ✓"},
    {"q":"₹5000 पर 10% वार्षिक चक्रवृद्धि ब्याज (वार्षिक संयोजन) से 3 वर्ष का चक्रवृद्धि ब्याज कितना होगा?","o":["₹1500","₹1550","₹1655","₹1605"],"a":2,"e":"<b>हल:</b><br>चरण 1: सूत्र — A = P(1 + R/100)ᵀ<br>चरण 2: A = 5000 × (1.1)³ = 5000 × 1.331 = 6655<br>चरण 3: CI = 6655 − 5000 = 1655<br>अतः उत्तर = <b>₹1655</b><br><b>शॉर्टकट:</b> 10% पर 3 वर्ष का प्रभावी दर = 33.1% → 5000 का 33.1% = ₹1655<br><b>ध्यान दें:</b> ₹1500 साधारण ब्याज है; ₹1550 केवल 2 वर्ष का संयोजन जोड़ने से आता है।"},
    {"q":"चक्रवृद्धि ब्याज पर कोई राशि 2 वर्ष में ₹4840 और 3 वर्ष में ₹5324 हो जाती है। मूलधन क्या है?","o":["₹3600","₹4200","₹4400","₹4000"],"a":3,"e":"<b>हल:</b><br>चरण 1: तीसरे वर्ष का ब्याज = 5324 − 4840 = ₹484<br>चरण 2: R = 484 × 100 ÷ 4840 = 10%<br>चरण 3: P × (1.1)² = 4840 → P = 4840 ÷ 1.21 = 4000<br>अतः उत्तर = <b>₹4000</b><br><b>ध्यान दें:</b> ₹4400 = 4840 ÷ 1.1 है, जो केवल एक वर्ष पीछे जाता है; 2 वर्ष पीछे जाने के लिए 1.21 से भाग दें।"},
    {"q":"₹10000 पर पहले वर्ष 10% तथा दूसरे वर्ष 20% वार्षिक चक्रवृद्धि ब्याज की दर हो, तो 2 वर्ष का चक्रवृद्धि ब्याज कितना होगा?","o":["₹3200","₹3000","₹3100","₹3300"],"a":0,"e":"<b>हल:</b><br>चरण 1: पहले वर्ष के बाद राशि = 10000 × 1.1 = 11000<br>चरण 2: दूसरे वर्ष 20% → 11000 × 1.2 = 13200<br>चरण 3: CI = 13200 − 10000 = 3200<br>अतः उत्तर = <b>₹3200</b><br><b>शॉर्टकट:</b> प्रभावी दर = a + b + ab/100 = 10 + 20 + 2 = 32%<br><b>ध्यान दें:</b> ₹3000 साधारण ब्याज (10% + 20%) है।"},
    {"q":"एक व्यक्ति ने ₹6000 साधारण ब्याज पर उधार लिए और 3 वर्ष बाद ₹7800 देकर पूरा ऋण चुका दिया। वार्षिक दर क्या थी?","o":["8%","9%","10%","12%"],"a":2,"e":"<b>हल:</b><br>चरण 1: SI = 7800 − 6000 = ₹1800<br>चरण 2: R = 1800 × 100 ÷ (6000 × 3)<br>चरण 3: = 180000 ÷ 18000 = 10<br>अतः उत्तर = <b>10%</b>"},
    {"q":"समान दर पर ₹x का 3 वर्ष का साधारण ब्याज और ₹(x + 2000) का 2 वर्ष का साधारण ब्याज बराबर है। x का मान क्या है?","o":["₹6000","₹4000","₹2000","₹3000"],"a":1,"e":"<b>हल:</b><br>चरण 1: दर समान → SI ∝ P × T: x × 3 = (x + 2000) × 2<br>चरण 2: 3x = 2x + 4000<br>चरण 3: x = 4000<br>अतः उत्तर = <b>₹4000</b><br><b>जाँच:</b> 4000 × 3 = 12000 = 6000 × 2 ✓"},
    {"q":"₹800 साधारण ब्याज पर 4 वर्ष में ₹960 हो जाते हैं। यदि दर 3% बढ़ा दी जाए तो ₹800, 4 वर्ष में कितने हो जाएँगे?","o":["₹1052","₹1056","₹1080","₹1096"],"a":1,"e":"<b>हल:</b><br>चरण 1: SI = 960 − 800 = ₹160 → R = 160 × 100 ÷ (800 × 4) = 5%<br>चरण 2: नई दर = 5 + 3 = 8% → SI = 800 × 8 × 4 ÷ 100 = ₹256<br>चरण 3: मिश्रधन = 800 + 256 = 1056<br>अतः उत्तर = <b>₹1056</b><br><b>शॉर्टकट:</b> अतिरिक्त ब्याज = 800 × 3 × 4 ÷ 100 = 96 → 960 + 96 = ₹1056<br><b>ध्यान दें:</b> ₹1052 तब आता है जब अतिरिक्त ब्याज 92 (गलत गुणा) जोड़ें; दर बढ़ने का असर पूरे 4 वर्ष पर होता है।"},
    {"q":"एक व्यक्ति 10% वार्षिक साधारण ब्याज पर हर वर्ष की शुरुआत में ₹2000 जमा करता है (3 वर्ष तक)। तीसरे वर्ष के अंत में कुल मिश्रधन कितना होगा?","o":["₹6600","₹7800","₹6900","₹7200"],"a":3,"e":"<b>हल:</b><br>चरण 1: पहली जमा (वर्ष 1 की शुरुआत) 3 वर्ष ब्याज कमाती है → 2000 × 1.3 = 2600<br>चरण 2: दूसरी जमा 2 वर्ष → 2000 × 1.2 = 2400; तीसरी जमा 1 वर्ष → 2000 × 1.1 = 2200<br>चरण 3: कुल = 2600 + 2400 + 2200 = 7200<br>अतः उत्तर = <b>₹7200</b><br><b>ध्यान दें:</b> ₹6600 तब आता है जब हर जमा पर केवल 1 वर्ष का ब्याज लें; ₹7800 तब जब तीनों पर 3 वर्ष का ब्याज लगा दें।"},
    {"q":"किसी राशि पर 8 वर्ष में साधारण ब्याज मूलधन का 2/5 हो जाता है। उसी दर से ₹4500 का 3 वर्ष का साधारण ब्याज कितना होगा?","o":["₹675","₹540","₹720","₹600"],"a":0,"e":"<b>हल:</b><br>चरण 1: 8 वर्ष में SI = P का 2/5 = 40% → R = 40 ÷ 8 = 5%<br>चरण 2: ₹4500 पर 5% से 3 वर्ष का SI = 4500 × 5 × 3 ÷ 100<br>चरण 3: = 45 × 15 = 675<br>अतः उत्तर = <b>₹675</b>"},
    {"q":"8% वार्षिक साधारण ब्याज पर कितने वर्ष में ब्याज, मिश्रधन का 3/5 हो जाएगा?","o":["7½ वर्ष","12½ वर्ष","18¾ वर्ष","20 वर्ष"],"a":2,"e":"<b>हल:</b><br>चरण 1: SI = 3/5 × मिश्रधन = 3/5 × (P + SI)<br>चरण 2: 5 SI = 3P + 3 SI → 2 SI = 3P → SI = 1.5P = मूलधन का 150%<br>चरण 3: T = 150 ÷ 8 = 18.75 = 18¾<br>अतः उत्तर = <b>18¾ वर्ष</b><br><b>शॉर्टकट:</b> SI : A = 3 : 5 → SI : P = 3 : 2 → 150%<br><b>ध्यान दें:</b> 7½ वर्ष तब आता है जब SI को मूलधन का 3/5 (60%) मान लें — यहाँ 3/5 मिश्रधन का है।"},
    {"q":"दो राशियों पर साधारण ब्याज की दरों का अनुपात 5 : 4, समय का अनुपात 3 : 2 तथा प्राप्त ब्याजों का अनुपात 3 : 2 है। मूलधनों का अनुपात क्या है?","o":["4 : 5","5 : 4","3 : 2","2 : 3"],"a":0,"e":"<b>हल:</b><br>चरण 1: SI = P × R × T ÷ 100 → P = 100 × SI ÷ (R × T); अतः P ∝ SI ÷ (R × T)<br>चरण 2: P₁ : P₂ = 3/(5 × 3) : 2/(4 × 2) = 3/15 : 2/8 = 1/5 : 1/4<br>चरण 3: 20 से गुणा करें → 4 : 5<br>अतः उत्तर = <b>4 : 5</b><br><b>ध्यान दें:</b> 5 : 4 उल्टा अनुपात है (1/5 : 1/4 को उलटने की भूल)।"},
    {"q":"₹64 साधारण ब्याज पर 2 वर्ष में ₹83.20 हो जाते हैं। उसी दर पर ₹86, 4 वर्ष में कितने हो जाएँगे?","o":["₹129","₹124.40","₹141.80","₹137.60"],"a":3,"e":"<b>हल:</b><br>चरण 1: SI = 83.20 − 64 = ₹19.20 → R = 19.20 × 100 ÷ (64 × 2) = 1920 ÷ 128 = 15%<br>चरण 2: 4 वर्ष में ब्याज = 15 × 4 = 60% → मिश्रधन = मूलधन का 160%<br>चरण 3: 86 × 160/100 = 137.60<br>अतः उत्तर = <b>₹137.60</b><br><b>ध्यान दें:</b> ₹124.40 = 86 + 2 × 19.20 है — दूसरी राशि पर पुराने ब्याज को जोड़ना गलत है, दर निकालकर नए मूलधन पर लगाएँ।"},
    {"q":"एक बैंक प्रत्येक ₹1000 पर हर तिमाही ₹25 साधारण ब्याज देता है। ₹6000 पर 1½ वर्ष का ब्याज कितना होगा?","o":["₹225","₹900","₹600","₹1350"],"a":1,"e":"<b>हल:</b><br>चरण 1: ₹1000 पर हर तिमाही ₹25 → तिमाही दर = 2.5% → वार्षिक दर = 2.5 × 4 = 10%<br>चरण 2: SI = 6000 × 10 × 1.5 ÷ 100<br>चरण 3: = 900<br>अतः उत्तर = <b>₹900</b><br><b>शॉर्टकट:</b> 1½ वर्ष = 6 तिमाही; 6000 पर हर तिमाही ₹150 → 6 × 150 = ₹900<br><b>ध्यान दें:</b> ₹225 केवल 1.5 तिमाही का ब्याज है।"},
    {"q":"साधारण ब्याज पर किसी राशि का 6 वर्ष का ब्याज ₹2160 है तथा 10 वर्ष बाद मिश्रधन ₹7600 हो जाता है। मूलधन क्या है?","o":["₹3600","₹3800","₹4000","₹4400"],"a":2,"e":"<b>हल:</b><br>चरण 1: 6 वर्ष का ब्याज ₹2160 → 1 वर्ष का ब्याज = 2160 ÷ 6 = ₹360<br>चरण 2: 10 वर्ष का ब्याज = 360 × 10 = ₹3600<br>चरण 3: मूलधन = 7600 − 3600 = 4000<br>अतः उत्तर = <b>₹4000</b><br><b>ध्यान दें:</b> ₹3600 दस वर्ष का ब्याज है, मूलधन नहीं; ₹4400 तब आता है जब 7600 − 3200 करें।"}
  ]
});
